async function createWorkflowUI(p,title='Мой процесс с контрольными точками'){
 const area=p.getByLabel('Поэтапный процесс помощника',{exact:true});await area.getByRole('button',{name:'Новый процесс',exact:true}).click();await p.getByLabel('Название процесса',{exact:true}).fill(title);await p.getByRole('button',{name:'Предпросмотр процесса',exact:true}).click();await p.getByRole('button',{name:'Подтвердить план процесса',exact:true}).click();await p.getByText('План сохранён. Ни один шаг ещё не запускался.',{exact:true}).waitFor();return area;
}
async function sendWorkflow(p,message=''){
 const area=p.getByLabel('Поэтапный процесс помощника',{exact:true});await p.getByLabel('Сообщение для текущего шага',{exact:true}).fill(message);await area.getByRole('button',{name:'Проверить текущий шаг',exact:true}).click();await p.getByRole('button',{name:'Подтвердить вызов модели шага',exact:true}).click();await p.waitForFunction(()=>{const e=document.querySelector('textarea[aria-label="Сообщение для текущего шага"]');return e&&!e.disabled&&e.value==='';});return area;
}
