test('assistant workflow desktop: cancellation cannot auto-retry, explicit acknowledgement only unlocks new preview',async()=>{
 const p=await page();await create(p);const area=await createWorkflowUI(p,'Оборванный шаг');await p.getByLabel('Сообщение для текущего шага',{exact:true}).fill('ПОДОЖДИ, уточни');await area.getByRole('button',{name:'Проверить текущий шаг',exact:true}).click();await p.getByRole('button',{name:'Подтвердить вызов модели шага',exact:true}).click();await area.getByRole('button',{name:'Остановить шаг процесса',exact:true}).waitFor();await p.waitForTimeout(200);await area.getByRole('button',{name:'Остановить шаг процесса',exact:true}).click();await area.getByRole('button',{name:'Обновить контрольные точки',exact:true}).click();await area.getByRole('button',{name:'Проверить сохранённый ответ шага',exact:true}).waitFor();const before=calls().length,retry=area.getByRole('button',{name:'Разрешить новую попытку шага',exact:true});assert.equal(await retry.isDisabled(),true);await area.getByRole('button',{name:'Проверить сохранённый ответ шага',exact:true}).click();await area.getByText(/Сохранённого ответа пока нет/).waitFor();assert.equal(calls().length,before);await area.getByLabel('Понимаю риск повторной оплаты; разрешаю новую попытку, только если сохранённого ответа нет',{exact:true}).check();await retry.click();await area.getByText('Готов к запуску',{exact:true}).waitFor();assert.equal(calls().length,before);assert.equal(await p.getByRole('button',{name:'Подтвердить вызов модели шага',exact:true}).count(),0);await close(p);
});

async function planPage(){const p=await page();await p.getByLabel('Файлы процесса помощника',{exact:true}).setInputFiles({name:'my-cycle.md',mimeType:'text/markdown',buffer:Buffer.from('Мой процесс:\nНапиши оригинальный документальный сценарий.\nДлительность ролика — 12 минут.\nПотом подготовь промпты изображений.')});await create(p);return p;}
async function planSend(p,text){const area=p.getByLabel('Разбор файла или промпта в план',{exact:true});await p.getByLabel('Промпт для разбора процесса',{exact:true}).fill(text);await area.getByRole('button',{name:'Проверить разбор процесса',exact:true}).click();const readyReview=p.waitForResponse(r=>r.url().includes('/api/assistant/plan-review/')&&r.ok());await p.getByRole('button',{name:'Подтвердить AI-разбор процесса',exact:true}).click();await readyReview;await area.getByLabel('Требования и источники плана',{exact:true}).waitFor();await p.waitForFunction(()=>{const e=document.querySelector('textarea[aria-label="Промпт для разбора процесса"]');return e&&!e.disabled;});return area;}
