 await planSend(p,'Подготовь оригинальный документальный сценарий на 12 минут.');await area.getByText('Текущий промпт пользователя · prompt · строки 1–1',{exact:true}).waitFor();await area.getByRole('checkbox').check();await area.getByRole('button',{name:'Перенести разбор в черновик процесса',exact:true}).click();await p.getByLabel('Название шага 1',{exact:true}).fill('Сценарий с моими правками');await p.getByRole('button',{name:'Предпросмотр процесса',exact:true}).click();await p.getByRole('button',{name:'Подтвердить план процесса',exact:true}).click();await p.getByText(/план изменён вручную после разбора/).waitFor();const selected=await p.getByLabel('Сохранённый процесс',{exact:true}).inputValue(),saved=(await(await req('/assistant/workflows/'+selected)).json()).data;assert.equal(saved.origin.edited,true);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await area.scrollIntoViewIfNeeded();await shot(p,'assistant-plan-light-1024');await close(p);
