 const p=await planPage(),area=p.getByLabel('Разбор файла или промпта в план',{exact:true}),before=calls().length;await p.getByLabel('Промпт для разбора процесса',{exact:true}).fill('НЕВЕРНАЯ ЦИТАТА. Разбери мой процесс.');await area.getByRole('button',{name:'Проверить разбор процесса',exact:true}).click();await p.getByRole('button',{name:'Подтвердить AI-разбор процесса',exact:true}).click();await area.getByText(/цитата отсутствует/).waitFor();assert.equal(calls().length,before+1);assert.equal(await area.getByLabel('Требования и источники плана',{exact:true}).count(),0);
