const editConsent='Проверил правки; принятые результаты сохраняются, но не проверяются заново по новым условиям';
async function workflowRecord(area){const id=await area.getByLabel('Сохранённый процесс',{exact:true}).inputValue();return (await(await req('/assistant/workflows/'+id)).json()).data;}
test('assistant workflow edit desktop: frozen accepted result, explicit future change, history and exact author without repeat',async()=>{
 const p=await page();await create(p);const area=await createWorkflowUI(p,'Правка будущего сценария');await sendWorkflow(p,'XIX век, документально, все существенные условия согласованы.');await area.getByRole('button',{name:'Принять результат шага',exact:true}).click();await area.getByText('Готов к запуску',{exact:true}).waitFor();const old=await workflowRecord(area),oldRun=(await(await req('/assistant/conversations/'+old.accepted[0].runId)).json()).data,before=calls().length;
 await area.getByRole('button',{name:'Проверить текущий шаг',exact:true}).click();await area.getByRole('button',{name:'Подтвердить вызов модели шага',exact:true}).waitFor();const edit=area.getByLabel('Изменение сохранённого процесса',{exact:true});await edit.getByRole('button',{name:'Изменить будущие шаги',exact:true}).click();assert.equal(await edit.getByLabel('Правка: название шага 1',{exact:true}).isDisabled(),true);await edit.getByLabel('Правка: задание шага 2',{exact:true}).fill('Напиши оригинальный сценарий на 10 минут, вместо прежних 12 минут.');await edit.getByLabel('Причина изменения процесса',{exact:true}).fill('Пользователь сократил длительность до 10 минут.');await edit.getByRole('button',{name:'Предпросмотр правок процесса',exact:true}).click();assert.equal(await edit.getByRole('button',{name:'Подтвердить правки процесса',exact:true}).isDisabled(),true);assert.equal(calls().length,before);await edit.getByLabel(editConsent,{exact:true}).check();await edit.getByRole('button',{name:'Подтвердить правки процесса',exact:true}).click();await area.getByText('План изменён. Принятые результаты сохранены; AI и следующий шаг не запускались.',{exact:true}).waitFor();const saved=await workflowRecord(area);assert.deepEqual(saved.accepted,old.accepted);assert.equal(saved.runId,old.runId);assert.equal(saved.edits[0].steps[1].instructions,old.steps[1].instructions);assert.equal(calls().length,before);assert.equal(await area.getByRole('button',{name:'Подтвердить вызов модели шага',exact:true}).count(),0);assert.deepEqual((await(await req('/assistant/conversations/'+old.accepted[0].runId)).json()).data,oldRun);
 await edit.getByText('История правок процесса · 1/20',{exact:true}).click();await edit.scrollIntoViewIfNeeded();await shot(p,'assistant-workflow-edit-dark');await sendWorkflow(p);assert.equal(calls().length,before+1);assert.equal(calls().at(-1).model,'fixture-author');await close(p);
});
test('assistant workflow edit desktop: waiting current locked, changes invalidate consent, cancel and reopen preserve saved plan',async()=>{
 const p=await page();await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>document.documentElement.classList.remove('dark'));await create(p);const area=await createWorkflowUI(p,'Уточнение будущих шагов');await sendWorkflow(p);await area.getByText('Нужны ответы',{exact:true}).waitFor();const old=await workflowRecord(area),before=calls().length,edit=area.getByLabel('Изменение сохранённого процесса',{exact:true});await edit.getByRole('button',{name:'Изменить будущие шаги',exact:true}).click();assert.equal(await edit.getByLabel('Правка: роль шага 1',{exact:true}).isDisabled(),true);await edit.getByLabel('Правка: название шага 2',{exact:true}).fill('Будущий сценарий по уточнённым условиям');await edit.getByLabel('Причина изменения процесса',{exact:true}).fill('Уточняется только будущий этап, текущий ответ сохраняется.');await edit.getByRole('button',{name:'Предпросмотр правок процесса',exact:true}).click();await edit.getByLabel(editConsent,{exact:true}).check();await edit.getByLabel('Правка: название процесса',{exact:true}).fill('Изменённый будущий процесс');assert.equal(await edit.getByRole('button',{name:'Подтвердить правки процесса',exact:true}).count(),0);assert.deepEqual(await workflowRecord(area),old);await edit.getByRole('button',{name:'Предпросмотр правок процесса',exact:true}).click();assert.equal(await edit.getByLabel(editConsent,{exact:true}).isChecked(),false);await edit.getByLabel(editConsent,{exact:true}).check();await edit.getByRole('button',{name:'Подтвердить правки процесса',exact:true}).click();await area.getByText('План изменён. Принятые результаты сохранены; AI и следующий шаг не запускались.',{exact:true}).waitFor();const saved=await workflowRecord(area);assert.equal(saved.phase,'waiting');assert.equal(saved.resultRunId,old.resultRunId);assert.equal(calls().length,before);await p.getByRole('button',{name:'Закрыть помощника',exact:true}).click();await p.getByRole('button',{name:'Открыть помощника',exact:true}).click();await area.getByText('Изменённый будущий процесс · принято 0/2',{exact:true}).waitFor();assert.deepEqual(await workflowRecord(area),saved);await area.getByText('История правок процесса · 1/20',{exact:true}).click();await area.getByLabel('Изменение сохранённого процесса',{exact:true}).scrollIntoViewIfNeeded();await shot(p,'assistant-workflow-edit-light-1024');assert.equal(calls().length,before);await close(p);
});
test('assistant workflow edit HTTP: strict confirmation, foreign Origin and unauthenticated calls denied; stale and pending cannot mutate',async()=>{
 const run=(await(await req('/assistant/conversations',{title:'Правки API',roles:{routine:{provider:'anthropic',model:'fixture-routine'},script:{provider:'anthropic',model:'fixture-author'},imagePrompt:null,animationPrompt:null},documents:[]})).json()).data,draft={attemptId:crypto.randomUUID(),runId:run.id,title:'Исходный процесс API',steps:[{title:'Уточнить условия',task:'routine',instructions:'Уточни существенные условия перед сценарием.'}]},vp=(await(await req('/assistant/workflow-preview',draft)).json()).data,old=(await(await req('/assistant/workflows',{...draft,previewHash:vp.hash,confirmed:true})).json()).data,input={id:old.id,revision:old.revision,title:'Новое имя API',steps:old.steps,reason:'Пользователь уточнил название процесса.'},before=calls().length,view=(await(await req('/assistant/workflow-edit-preview',input)).json()).data;
 assert.equal((await req('/assistant/workflow-edit-preview',input,null)).status,401);const foreign=await fetch(BASE+'/api/assistant/workflow-edit',{method:'POST',headers:{cookie,'content-type':'application/json',origin:'https://foreign.invalid'},body:JSON.stringify({...input,previewHash:view.hash,confirmed:true})});assert.equal(foreign.status,403);assert.equal((await req('/assistant/workflow-edit',{...input,previewHash:view.hash,confirmed:false})).status,400);const saved=(await(await req('/assistant/workflow-edit',{...input,previewHash:view.hash,confirmed:true})).json()).data;assert.equal(saved.edits.length,1);assert.equal((await req('/assistant/workflow-edit',{...input,previewHash:view.hash,confirmed:true})).status,409);assert.equal(calls().length,before);
 const step={id:saved.id,revision:saved.revision,message:'ПОДОЖДИ',currentPath:'/script',attemptId:crypto.randomUUID()},sp=(await(await req('/assistant/workflow-step-preview',step)).json()).data,started=await req('/assistant/workflow-step',{...step,previewHash:sp.hash,confirmed:true}),job=(await started.json()).data.jobId,pending=(await(await req('/assistant/workflows/'+saved.id)).json()).data;assert.equal((await req('/assistant/workflow-edit-preview',{...input,revision:pending.revision,title:'Обход попытки API'})).status,409);await(await req('/jobs/'+job+'/stream')).text();
});

const reusableConsent='Проверил карточку: убрал разовые темы, ссылки и условия; согласен сохранить повторяемый навык';
const intakeConsent='Проверил условия нового видео и хочу подготовить черновик процесса по этому навыку';
async function skillPreviewUI(p,area,name){const save=area.getByLabel('Сохранение процесса как навыка',{exact:true});await save.getByRole('button',{name:'Да, подготовить навык процесса',exact:true}).click();await save.getByLabel('Название навыка процесса',{exact:true}).fill(name);await save.getByRole('button',{name:'Предпросмотр навыка процесса',exact:true}).click();await save.getByLabel(reusableConsent,{exact:true}).waitFor();return save;}
async function saveSkillUI(p,area,name){const save=await skillPreviewUI(p,area,name);await save.getByLabel(reusableConsent,{exact:true}).check();await save.getByRole('button',{name:'Подтвердить сохранение навыка процесса',exact:true}).click();await save.getByRole('status').filter({hasText:'Сохранён навык процесса: '+name}).waitFor();await p.waitForFunction(()=>{const e=document.querySelector('button');return !Array.from(document.querySelectorAll('button')).find(x=>x.textContent==='Новый диалог / модели')?.disabled;});return save;}
test('assistant process skill desktop: proposal is not saved, edits revoke consent, explicit local save and original plan intact',async()=>{
 const p=await page();await create(p);const area=await createWorkflowUI(p,'Именованный повторяемый процесс'),old=await workflowRecord(area),before=calls().length,name='Текстовый цикл для новых видео';let save=await skillPreviewUI(p,area,name);assert.equal(await save.getByRole('button',{name:'Подтвердить сохранение навыка процесса',exact:true}).isDisabled(),true);assert.equal((await(await req('/assistant/state')).json()).data.skills.some(s=>s.name===name),false);await save.getByLabel(reusableConsent,{exact:true}).check();await save.getByLabel('Описание навыка процесса',{exact:true}).fill('Использовать для нового документального видео с отдельными условиями и согласуемыми этапами.');assert.equal(await save.getByRole('button',{name:'Подтвердить сохранение навыка процесса',exact:true}).count(),0);await save.getByRole('button',{name:'Предпросмотр навыка процесса',exact:true}).click();assert.equal(await save.getByLabel(reusableConsent,{exact:true}).isChecked(),false);await save.getByRole('button',{name:'Не сохранять процесс',exact:true}).click();assert.equal((await(await req('/assistant/state')).json()).data.skills.some(s=>s.name===name),false);save=await saveSkillUI(p,area,name);const skill=(await(await req('/assistant/state')).json()).data.skills.find(s=>s.name===name);assert.ok(skill.process);assert.equal(skill.process.steps.length,2);assert.ok(!JSON.stringify(skill).includes('fixture-author'));assert.deepEqual(await workflowRecord(area),old);assert.equal(calls().length,before);await save.scrollIntoViewIfNeeded();await shot(p,'assistant-process-skill-save-dark');await close(p);
});
