lick();await area.getByText(name+' · принято 0/2',{exact:true}).waitFor();assert.deepEqual(await workflowRecord(area),old);await area.getByText('Условия этого запуска · '+name,{exact:true}).click();await area.getByText('Условия этого запуска · '+name,{exact:true}).scrollIntoViewIfNeeded();await shot(p,'assistant-process-skill-apply-light-1024');assert.equal(calls().length,before);await close(p);
