test('assistant TTS desktop: provider 503 never retries or replaces voice; reopen preserves unknown lock',async()=>{const f=await executionFixture('fish-farm/synthetic-error'),p=await page();await create(p);await executionForm(p,f);const n=speechCalls().length;await p.getByRole('button',{name:'Проверить запуск части 1',exact:true}).click();await p.getByLabel('Подтверждаю платный TTS одной части',{exact:true}).check();await p.getByRole('button',{name:'Подтвердить один TTS-запрос',exact:true}).click();await p.getByText(/Исход неизвестен — повтор заблокирован/).waitFor();assert.equal(speechCalls().length,n+1);assert.equal(await p.getByRole('button',{name:'Проверить запуск части 1',exact:true}).count(),0);assert.ok(!(await p.getByRole('dialog').innerText()).includes('PRIVATE_SYNTHETIC_PROVIDER_ERROR'));await p.getByRole('button',{name:'Закрыть помощника',exact:true}).click();await p.getByRole('button',{name:'Открыть помощника',exact:true}).click();await executionForm(p,f);await p.getByText(/Исход неизвестен — повтор заблокирован/).waitFor();assert.equal(speechCalls().length,n+1);await close(p);});
test('assistant TTS desktop: close cancels waiting request, reopen cannot automatically repeat paid part',async()=>{const f=await executionFixture('fish-farm/synthetic-slow'),p=await page();await create(p);await executionForm(p,f);const n=speechCalls().length;await p.getByRole('button',{name:'Проверить запуск части 1',exact:true}).click();await p.getByLabel('Подтверждаю платный TTS одной части',{exact:true}).check();await p.getByRole('button',{name:'Подтвердить один TTS-запрос',exact:true}).click();await p.getByRole('button',{name:'Остановить TTS',exact:true}).waitFor();for(let i=0;i<40&&speechCalls().length===n;i++)await p.waitForTimeout(25);assert.equal(speechCalls().length,n+1);await p.getByRole('button',{name:'Закрыть помощника',exact:true}).click();await p.waitForTimeout(300);await p.getByRole('button',{name:'Открыть помощника',exact:true}).click();await executionForm(p,f);await p.getByText(/Исход неизвестен — повтор заблокирован/).waitFor();assert.equal(speechCalls().length,n+1);await close(p);});
test('assistant TTS HTTP: auth, Origin, false consent, stale preview, durable replay and local attach guards',async()=>{const f=await executionFixture(),n=speechCalls().length;assert.equal((await req('/assistant/voice-part-preview',f.ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/voice-part-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(f.ask)})).status,403);const pv=(await(await req('/assistant/voice-part-preview',f.ask)).json()).data;assert.equal((await req('/assistant/voice-part',{...f.ask,previewHash:pv.hash,confirmed:false})).status,400);await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Другой материал',data:'KEEP'});assert.equal((await req('/assistant/voice-part',{...f.ask,previewHash:pv.hash,confirmed:true})).status,409);const fresh=(await(await req('/assistant/voice-part-preview',f.ask)).json()).data,send={...f.ask,previewHash:fresh.hash,confirmed:true},r=await req('/assistant/voice-part',send);assert.equal(r.status,200);await(await req('/jobs/'+(await r.json()).data.jobId+'/stream')).text();assert.equal((await req('/assistant/voice-part',send)).status,409);assert.equal(speechCalls().length,n+1);const attach=(await(await req('/assistant/voice-attach-preview',f.ask)).json()).data;assert.equal((await req('/assistant/voice-attach',{...f.ask,previewHash:attach.hash,confirmed:false})).status,400);assert.equal((await req('/assistant/voice-attach',{...f.ask,previewHash:attach.hash,confirmed:true})).status,200);assert.equal(speechCalls().length,n+1);});
test('assistant TTS desktop: light 1024 result and project audio keep explicit part label without overflow',async()=>{const f=await executionFixture(),pv=(await(await req('/assistant/voice-part-preview',f.ask)).json()).data,r=(await(await req('/assistant/voice-part',{...f.ask,previewHash:pv.hash,confirmed:true})).json()).data;await(await req('/jobs/'+r.jobId+'/stream')).text();const n=speechCalls().length,p=await page();await create(p);await executionForm(p,f);await p.getByRole('link',{name:'Скачать MP3 части 1',exact:true}).waitFor();await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await shot(p,'assistant-tts-result-light-1024');assert.equal(speechCalls().length,n);await close(p);});

async function assemblyFixture(multi=true){const f=await voiceFixture();if(multi){const script=(await(await req('/projects/'+f.project.id+'/artifacts',{kind:'script',title:'Полный длинный сценарий',data:{script:'Город просыпается. '.repeat(100)}})).json()).data;f.input.sourceArtifactId=script.id;}const pv=(await(await req('/assistant/voice-preview',f.input)).json()).data,saved=(await(await req('/assistant/voice-preparations',{...f.input,previewHash:pv.hash,confirmed:true})).json()).data,ask={projectId:f.project.id,preparationId:saved.artifact.id};const state=(await(await req(`/assistant/voice-state/${ask.projectId}/${ask.preparationId}`)).json()).data;for(const part of state.parts){const d={...ask,part:part.part},view=(await(await req('/assistant/voice-part-preview',d)).json()).data,job=(await(await req('/assistant/voice-part',{...d,previewHash:view.hash,confirmed:true})).json()).data;await(await req('/jobs/'+job.jobId+'/stream')).text();}return {...f,preparationId:saved.artifact.id,assemblyAsk:ask};}
async function checkAssembly(p){await p.getByRole('button',{name:'Проверить сборку всех частей без AI',exact:true}).click();await p.getByLabel('Предпросмотр сборки озвучки',{exact:true}).waitFor();}
async function assembleUI(p){await checkAssembly(p);const button=p.getByRole('button',{name:'Собрать единый MP3 локально',exact:true});assert.equal(await button.isDisabled(),true);await p.getByLabel('Подтверждаю локальную сборку без AI',{exact:true}).check();await button.click();await p.getByLabel('Готовый единый MP3',{exact:true}).waitFor();}
test('assistant assembly desktop: explicit all-part preview, local build, exact download and separate attachment without provider',async()=>{const f=await assemblyFixture(),p=await page();await create(p);await executionForm(p,f);const n=speechCalls().length,before=(await(await req('/projects/'+f.project.id)).json()).data.artifacts.length;await assembleUI(p);assert.equal(speechCalls().length,n);const result=p.getByLabel('Готовый единый MP3',{exact:true}),link=result.getByRole('link',{name:'Скачать единый MP3',exact:true}),url=await link.getAttribute('href');const response=await p.context().request.get(BASE+url);assert.equal(response.status(),200);const bytes=await response.body();const preview=(await(await req('/assistant/voice-assembly-preview',f.assemblyAsk)).json()).data;assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),preview.existing.audioHash);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,before);await result.getByRole('button',{name:'Добавить единый MP3 в проект · просмотр',exact:true}).click();const save=p.getByRole('button',{name:'Сохранить единый MP3 в проект',exact:true});assert.equal(await save.isDisabled(),true);await p.getByLabel('Подтверждаю добавление единого MP3',{exact:true}).check();await save.click();await p.getByRole('link',{name:'Открыть проект с единой озвучкой',exact:true}).waitFor();const after=(await(await req('/projects/'+f.project.id)).json()).data;assert.equal(after.artifacts.length,before+1);assert.equal(after.artifacts.at(-1).data.chunks,2);assert.equal(after.artifacts.at(-1).data.source,'assistant-voice-assembly');assert.equal(speechCalls().length,n);await shot(p,'assistant-assembly-result-dark');await close(p);});
test('assistant assembly desktop: reopen recovers completed MP3 without FFmpeg resend or speech; selection clears consent',async()=>{const f=await assemblyFixture(false),p=await page();await create(p);await executionForm(p,f);await checkAssembly(p);await p.getByLabel('Подтверждаю локальную сборку без AI',{exact:true}).check();await p.getByLabel('Подготовка запуска озвучки',{exact:true}).selectOption('');assert.equal(await p.getByLabel('Подтверждаю локальную сборку без AI',{exact:true}).count(),0);await p.getByLabel('Подготовка запуска озвучки',{exact:true}).selectOption(f.preparationId);await assembleUI(p);const n=speechCalls().length,first=(await(await req('/assistant/voice-assembly-preview',f.assemblyAsk)).json()).data.existing;await p.getByRole('button',{name:'Закрыть помощника',exact:true}).click();await p.getByRole('button',{name:'Открыть помощника',exact:true}).click();await executionForm(p,f);await checkAssembly(p);await p.getByLabel('Готовый единый MP3',{exact:true}).waitFor();assert.equal(await p.getByRole('button',{name:'Собрать единый MP3 локально',exact:true}).count(),0);assert.deepEqual((await(await req('/assistant/voice-assembly-preview',f.assemblyAsk)).json()).data.existing,first);assert.equal(speechCalls().length,n);await close(p);});
