async function independentConnection(){const r=await req('/assistant/tts-connections',{name:'Независимая озвучка',baseUrl:'http://127.0.0.1:'+compatiblePort+'/v1',local:true,auth:'bearer',apiKey:'SYNTHETIC_TTS_DESKTOP_KEY',confirmed:true});assert.equal(r.status,200);return (await r.json()).data;}
