test('assistant independent TTS desktop: light 1024 exact preparation and voice changes reset consent',async()=>{const f=await independentFixture(),p=await page();await p.setViewportSize({width:1024,height:900});await create(p);await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});const n=compatibleSpeechCalls.length;await independentReview(p,f);await p.getByLabel('Подтверждаю подготовку озвучки без генерации',{exact:true}).check();await shot(p,'assistant-independent-tts-light-1024');await p.getByLabel('Точный voice ID независимого TTS',{exact:true}).fill('different-voice');assert.equal(await p.getByLabel('Предпросмотр подготовки озвучки',{exact:true}).count(),0);await p.getByRole('button',{name:'Предпросмотр текста озвучки',exact:true}).click();await p.getByLabel('Предпросмотр подготовки озвучки',{exact:true}).waitFor();assert.equal(await p.getByLabel('Подтверждаю подготовку озвучки без генерации',{exact:true}).isChecked(),false);assert.equal(compatibleSpeechCalls.length,n);await close(p);});
test('assistant independent TTS HTTP: auth Origin strict schema profile pin and no probe',async()=>{const n=compatibleSpeechCalls.length,body={name:'Strict TTS',baseUrl:'http://127.0.0.1:'+compatiblePort+'/v1',local:true,auth:'none',apiKey:'',confirmed:true};assert.equal((await req('/assistant/tts-connections',body,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/tts-connections',{method:'POST',headers:{Cookie:cookie,Origin:'https://untrusted.example','content-type':'application/json'},body:JSON.stringify(body)})).status,403);for(const x of [{...body,confirmed:false},{...body,arbitraryHeader:'bad'},{...body,baseUrl:'http://192.168.1.2/v1'}])assert.equal((await req('/assistant/tts-connections',x)).status,400);const f=await independentFixture();assert.equal((await req('/assistant/voice-preview',{...f.input,tts:{...f.input.tts,connectionHash:'0'.repeat(64)}})).status,409);assert.equal(compatibleSpeechCalls.length,n);});
