test('assistant DOCX: HTTP auth, Origin, strict schema, size and extension restrictions',async()=>{
 const f=docxUpload(),body={name:f.name,base64:f.buffer.toString('base64')},before=calls().length;
 assert.equal((await req('/assistant/document-preview',body,null)).status,401);
 assert.equal((await fetch(BASE+'/api/assistant/document-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://untrusted.invalid','Content-Type':'application/json'},body:JSON.stringify(body)})).status,403);
 for(const q of [{...body,name:'x.pdf'},{...body,url:'https://untrusted.invalid'},{...body,base64:'not base64'},{...body,base64:Buffer.alloc(180001).toString('base64')}])assert.equal((await req('/assistant/document-preview',q)).status,400);
 const result=(await(await req('/assistant/document-preview',body)).json()).data;assert.match(result.text,/Сначала уточнить/);assert.equal(calls().length,before);assert.equal(compatibleCalls.length>=0,true);
});
test('assistant DOCX: mixed TXT and DOCX accepted together; reopening keeps text without extraction or generation',async()=>{
 const p=await page(),before=calls().length;await p.getByLabel('Файлы процесса помощника',{exact:true}).setInputFiles([docxUpload(),{name:'limits.txt',mimeType:'text/plain',buffer:Buffer.from('Не менять согласованный стиль.')}]);await p.getByLabel('Подтверждаю текст DOCX',{exact:true}).check();await p.getByRole('button',{name:'Добавить проверенные тексты',exact:true}).click();await create(p);const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));
 let extracts=0;p.on('request',r=>{if(r.url().endsWith('/assistant/document-preview'))extracts++;});await p.getByRole('button',{name:'Закрыть помощника',exact:true}).click();await p.getByRole('button',{name:'Открыть помощника',exact:true}).click();await p.getByLabel('Сообщение помощнику',{exact:true}).waitFor();assert.equal(extracts,0);assert.equal(calls().length,before);const saved=(await(await req('/assistant/conversations/'+id)).json()).data;assert.equal(saved.context.documents.length,2);assert.equal(saved.context.documents[1].text,'Не менять согласованный стиль.');await close(p);
});

test('assistant DOCX: delayed history and file reads stay independent, loading cannot enable premature creation',async()=>{
 const p=await page(900),before=calls().length;await p.route('**/api/assistant/document-preview',async r=>{await new Promise(resolve=>setTimeout(resolve,1800));await r.continue();});
 const state=p.waitForResponse(r=>r.url().endsWith('/api/assistant/state')&&r.ok());await p.getByLabel('Файлы процесса помощника',{exact:true}).setInputFiles(docxUpload());await state;
 assert.equal(await p.getByRole('button',{name:'Создать локальный диалог',exact:true}).isDisabled(),true);await p.getByLabel('Предпросмотр текста DOCX',{exact:true}).waitFor();await p.getByLabel('Подтверждаю текст DOCX',{exact:true}).check();await p.getByRole('button',{name:'Добавить проверенные тексты',exact:true}).click();await create(p);
 const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));assert.equal((await(await req('/assistant/conversations/'+id)).json()).data.context.documents.length,1);assert.equal(calls().length,before);await close(p);
});
test('assistant DOCX: accepted Word text becomes cited routine plan, explicit draft only and no author generation',async()=>{
 const p=await page(),before=calls().length;await uploadDocx(p,'Напиши оригинальный документальный сценарий.');await p.getByLabel('Подтверждаю текст DOCX',{exact:true}).check();await p.getByRole('button',{name:'Добавить проверенные тексты',exact:true}).click();await create(p);
 const area=await planSend(p,'Разбери мой процесс из Word. Ничего не запускай.');await area.getByText('мой-процесс.docx · document:0 · строки 1–1',{exact:true}).waitFor();assert.equal(calls().length,before+1);assert.equal(calls().at(-1).model,'fixture-routine');assert.equal(calls().at(-1).mode,'process-plan');
 await area.getByRole('checkbox').check();await area.getByRole('button',{name:'Перенести разбор в черновик процесса',exact:true}).click();assert.equal(await p.getByLabel('Роль шага 1',{exact:true}).inputValue(),'script');assert.equal(calls().length,before+1);await close(p);
});

async function storyboardFixture(){const project=(await(await req('/projects',{title:'Раскадровка '+crypto.randomUUID().slice(0,6)})).json()).data;const text='Первый сценарий. Город просыпается и жители выходят на улицы.\n'.repeat(9);const first=(await(await req('/projects/'+project.id+'/artifacts',{kind:'script',title:'Первая версия',data:{script:text}})).json()).data;await req('/projects/'+project.id+'/artifacts',{kind:'script',title:'Поздняя версия',data:{script:'Поздняя версия. '.repeat(20)}});return {project,first,text,ask:{projectId:project.id,sourceArtifactId:first.id}};}
