test('assistant storyboard: older exact script, destination consent protects existing draft, no AI',async()=>{const f=await storyboardFixture(),p=await page(),n=calls().length;await p.evaluate(()=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:'Старый черновик для сохранения',style:'universal',customStyle:'old option',imageModel:'midjourney',videoModel:'kling',clip:5})));await create(p);await storyboardForm(p,f);assert.ok((await p.getByLabel('Сценарий для раскадровки').innerText()).includes(f.text.trim()));assert.equal(calls().length,n);await p.getByRole('button',{name:'Открыть раскадровку для проверки',exact:true}).click();const review=p.getByLabel('Проверка передачи в раскадровку',{exact:true});await review.getByText('Новый текст целиком',{exact:true}).waitFor();const input=p.getByLabel('Сценарий',{exact:true});assert.equal(await input.inputValue(),'Старый черновик для сохранения');assert.equal(await review.getByRole('button',{name:'Заменить черновик без генерации'}).isDisabled(),true);await review.getByLabel('Подтверждаю замену черновика раскадровки').check();await review.getByRole('button',{name:'Заменить черновик без генерации'}).click();await review.waitFor({state:'detached'});assert.equal(await input.inputValue(),f.text);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);assert.equal(calls().length,n);assert.equal(await p.locator('a[href="/projects/'+f.project.id+'"]').count()>0,true);await close(p);});
test('assistant storyboard: cancellation keeps draft, no provider and no project mutation',async()=>{const f=await storyboardFixture(),p=await page();await p.evaluate(()=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:'Сохранённый черновик',style:'universal'})));await create(p);await storyboardForm(p,f);const n=calls().length;await p.getByRole('button',{name:'Открыть раскадровку для проверки'}).click();const r=p.getByLabel('Проверка передачи в раскадровку');await r.getByText('Новый текст целиком').waitFor();await r.getByRole('button',{name:'Отменить передачу'}).click();await r.waitFor({state:'detached'});assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'Сохранённый черновик');assert.equal(calls().length,n);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);await close(p);});
test('assistant storyboard: stale project blocks application and preserves draft',async()=>{const f=await storyboardFixture(),p=await page();await p.evaluate(()=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:'НЕ ТРОГАТЬ',style:'universal'})));await create(p);await storyboardForm(p,f);await p.getByRole('button',{name:'Открыть раскадровку для проверки'}).click();const r=p.getByLabel('Проверка передачи в раскадровку');await r.getByText('Новый текст целиком').waitFor();await r.getByLabel('Подтверждаю замену черновика раскадровки').check();await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Смена проекта',data:'KEEP'});await r.getByRole('button',{name:'Заменить черновик без генерации'}).click();await r.getByText(/Проект или сценарий изменились/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ ТРОГАТЬ');assert.equal(await r.getByLabel('Подтверждаю замену черновика раскадровки').isChecked(),false);await close(p);});
test('assistant storyboard HTTP: authentication, origin, strict fields, limits and changed snapshot',async()=>{const f=await storyboardFixture();assert.equal((await req('/assistant/storyboard-source-preview',f.ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/storyboard-source-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(f.ask)})).status,403);assert.equal((await req('/assistant/storyboard-source-preview',{...f.ask,text:'override'})).status,400);const a=(await(await req('/assistant/storyboard-source-preview',f.ask)).json()).data;assert.equal(a.text,f.text);await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Изменение',data:'KEEP'});const b=(await(await req('/assistant/storyboard-source-preview',f.ask)).json()).data;assert.notEqual(a.hash,b.hash);});
test('assistant storyboard: draft edit during server recheck stops replacement',async()=>{const f=await storyboardFixture(),p=await page();await p.evaluate(()=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:'Начальный черновик',style:'universal'})));await create(p);await storyboardForm(p,f);await p.getByRole('button',{name:'Открыть раскадровку для проверки'}).click();const r=p.getByLabel('Проверка передачи в раскадровку');await r.getByText('Новый текст целиком').waitFor();await r.getByLabel('Подтверждаю замену черновика раскадровки').check();let release,seen;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/storyboard-source-preview',async route=>{seen();await gate;await route.continue();});await r.getByRole('button',{name:'Заменить черновик без генерации'}).click();await started;await p.getByLabel('Сценарий',{exact:true}).fill('Новая правка во время проверки');release();await r.getByText(/Черновик изменился во время проверки/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'Новая правка во время проверки');assert.equal(await r.getByLabel('Подтверждаю замену черновика раскадровки').isChecked(),false);await close(p);});
test('assistant storyboard: from existing storyboard page, selection opens review without replacing draft',async()=>{const f=await storyboardFixture(),p=await page();await create(p);await p.getByRole('button',{name:'Закрыть помощника'}).click();await p.goto(BASE+'/storyboard');await p.getByLabel('Сценарий',{exact:true}).fill('Текст текущей открытой страницы');await p.getByRole('button',{name:'Открыть помощника'}).click();await p.getByLabel('Сообщение помощнику').waitFor();await storyboardForm(p,f);const n=calls().length;await p.getByRole('button',{name:'Открыть раскадровку для проверки'}).click();const r=p.getByLabel('Проверка передачи в раскадровку');await r.getByText('Новый текст целиком').waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'Текст текущей открытой страницы');await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await r.scrollIntoViewIfNeeded();await p.screenshot({path:OUT+'/assistant-storyboard-review-light.png'});assert.equal(calls().length,n);await close(p);});
test('assistant storyboard: same-length replacement recalculates scene preview for new text',async()=>{const f=await storyboardFixture(),p=await page(),old='A'.repeat(f.text.length);await p.evaluate(text=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:text,style:'universal'})),old);await create(p);await storyboardForm(p,f);const oldResponse=p.waitForResponse(r=>r.url().endsWith('/api/storyboard/segment')&&r.request().postDataJSON()?.script===old,{timeout:10000});await p.getByRole('button',{name:'Открыть раскадровку для проверки'}).click();await oldResponse;const r=p.getByLabel('Проверка передачи в раскадровку');await r.getByText('Новый текст целиком').waitFor();await r.getByLabel('Подтверждаю замену черновика раскадровки').check();const newResponse=p.waitForResponse(r=>r.url().endsWith('/api/storyboard/segment')&&r.request().postDataJSON()?.script===f.text,{timeout:10000});await r.getByRole('button',{name:'Заменить черновик без генерации'}).click();assert.equal((await newResponse).status(),200);assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),f.text);await close(p);});

async function savedStoryboardFixture(){const project=(await(await req('/projects',{title:'Проект снимка '+crypto.randomUUID().slice(0,6)})).json()).data;const old='Старый точный сценарий, важна каждая строка. Город просыпается.\n'.repeat(6),latest='НОВЕЙШИЙ СЦЕНАРИЙ НЕ ПОДСТАВЛЯТЬ. '.repeat(10);await req('/projects/'+project.id+'/artifacts',{kind:'script',title:'Исходный',data:{script:old}});await req('/projects/'+project.id+'/artifacts',{kind:'script',title:'Поздний',data:{script:latest}});const input={script:old,style:'universal',customStyle:'Мягкая акварель',imageModel:'flux',videoModel:'kling',clip:5,maxBatches:1,projectId:project.id};const hash=crypto.createHash('sha256').update(JSON.stringify(input)).digest('hex'),data={rows:[],batches:[],bible:{medium:'ink',palette:'blue',lighting:'day',camera:'fixed',mood:'calm',negative:'none',characters:[],locations:[]},totalUnits:1,totalSeconds:20,done:true,model:'synthetic',input:{style:'universal'}};const saved=(await(await req('/projects/'+project.id+'/artifacts',{kind:'storyboard',title:'С входом',data:{...data,inputSnapshot:{version:1,input,hash}}})).json()).data;const legacy=(await(await req('/projects/'+project.id+'/artifacts',{kind:'storyboard',title:'Старая без входа',data})).json()).data;return {project,input,old,latest,saved,legacy,data};}
async function openSaved(p,f,artifact){await p.getByRole('button',{name:'Закрыть помощника'}).click();await p.evaluate(()=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:'МОЙ ТЕКУЩИЙ ЧЕРНОВИК',style:'universal',customStyle:'НЕ ПЕРЕЗАПИСЫВАТЬ',imageModel:'midjourney',videoModel:'kling',clip:5})));await p.goto(BASE+'/storyboard?projectId='+f.project.id+'&artifact='+artifact.id);return p.getByLabel('Сохранённый вход раскадровки');}
test('storyboard saved input: legacy opens result without substituting latest or touching draft',async()=>{const f=await savedStoryboardFixture(),p=await page(),n=calls().length,r=await openSaved(p,f,f.legacy);await r.getByText(/полный вход не сохранён/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'МОЙ ТЕКУЩИЙ ЧЕРНОВИК');assert.equal((await r.innerText()).includes(f.latest),false);assert.equal(await r.getByRole('button',{name:'Восстановить вход без генерации'}).count(),0);assert.equal(calls().length,n);await close(p);});
test('storyboard saved input: exact snapshot, explicit consent, independent draft and settings',async()=>{const f=await savedStoryboardFixture(),p=await page(),n=calls().length,r=await openSaved(p,f,f.saved);await r.getByRole('button',{name:'Сравнить с черновиком'}).click();await r.getByText('Сохранённый текст целиком',{exact:false}).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'МОЙ ТЕКУЩИЙ ЧЕРНОВИК');assert.equal(await r.getByRole('button',{name:'Восстановить вход без генерации'}).isDisabled(),true);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await r.scrollIntoViewIfNeeded();assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await p.screenshot({path:OUT+'/storyboard-saved-review-light.png'});await r.getByLabel('Подтверждаю восстановление входа раскадровки').check();await r.getByRole('button',{name:'Восстановить вход без генерации'}).click();await p.waitForFunction(t=>document.querySelector('textarea[aria-label="Сценарий"]')?.value===t,f.old);assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),f.old);assert.equal(await p.getByPlaceholder('Например: тёмная акварель').inputValue(),'Мягкая акварель');assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,4);assert.equal(calls().length,n);await close(p);});
test('storyboard saved input: stale project stops restoration and preserves edits',async()=>{const f=await savedStoryboardFixture(),p=await page(),r=await openSaved(p,f,f.saved);await r.getByRole('button',{name:'Сравнить с черновиком'}).click();await r.getByLabel('Подтверждаю восстановление входа раскадровки').check();await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Изменение',data:'KEEP'});await r.getByRole('button',{name:'Восстановить вход без генерации'}).click();await r.getByText(/Проект, снимок или доступность настроек изменились/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'МОЙ ТЕКУЩИЙ ЧЕРНОВИК');assert.equal(await r.getByLabel('Подтверждаю восстановление входа раскадровки').isChecked(),false);await close(p);});
test('storyboard saved input: editing settings resets prior consent',async()=>{const f=await savedStoryboardFixture(),p=await page(),r=await openSaved(p,f,f.saved);await r.getByRole('button',{name:'Сравнить с черновиком'}).click();await r.getByLabel('Подтверждаю восстановление входа раскадровки').check();await p.getByPlaceholder('Например: тёмная акварель').fill('Другая настройка');await p.waitForFunction(()=>!document.querySelector('input[aria-label="Подтверждаю восстановление входа раскадровки"]').checked);assert.equal(await r.getByRole('button',{name:'Восстановить вход без генерации'}).isDisabled(),true);await close(p);});
test('storyboard saved input HTTP: auth, Origin, strict fields, tampered copy rejected',async()=>{const f=await savedStoryboardFixture(),ask={projectId:f.project.id,artifactId:f.saved.id};assert.equal((await req('/assistant/storyboard-saved-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/storyboard-saved-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);assert.equal((await req('/assistant/storyboard-saved-preview',{...ask,text:'spoof'})).status,400);const bad=(await(await req('/projects/'+f.project.id+'/artifacts',{kind:'storyboard',title:'Повреждённый',data:{...f.data,inputSnapshot:{version:1,input:f.input,hash:'0'.repeat(64)}}})).json()).data;assert.equal((await req('/assistant/storyboard-saved-preview',{projectId:f.project.id,artifactId:bad.id})).status,409);});
test('storyboard saved input: recheck refuses draft edited during request',async()=>{const f=await savedStoryboardFixture(),p=await page(),r=await openSaved(p,f,f.saved);await r.getByRole('button',{name:'Сравнить с черновиком'}).click();await r.getByLabel('Подтверждаю восстановление входа раскадровки').check();let release,seen;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/storyboard-saved-preview',async route=>{seen();await gate;await route.continue();});await r.getByRole('button',{name:'Восстановить вход без генерации'}).click();await started;await p.getByLabel('Сценарий',{exact:true}).fill('Правка во время проверки');release();await r.getByText(/Черновик изменился во время проверки/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'Правка во время проверки');await close(p);});
test('storyboard saved input: deleted style after review blocks replacement',async()=>{const f=await savedStoryboardFixture(),fields={name:'Синтетический стиль',group:'Тест',description:'Временный',anchor:'flat blue illustration for a quiet city',motion:'pedestrians walk slowly along the street',negative:'3d render',motionKind:'action'};const response=await req('/visual-styles',fields);assert.equal(response.status,200);const style=(await response.json()).data;const input={script:f.old,style:'universal',customStyle:'',visualStyleId:style.id,imageModel:'flux',videoModel:'kling',clip:5,maxBatches:1,projectId:f.project.id};const hash=crypto.createHash('sha256').update(JSON.stringify(input)).digest('hex');const a=(await(await req('/projects/'+f.project.id+'/artifacts',{kind:'storyboard',title:'Со стилем',data:{...f.data,inputSnapshot:{version:1,input,hash}}})).json()).data;const p=await page(),r=await openSaved(p,f,a);await r.getByRole('button',{name:'Сравнить с черновиком'}).click();await r.getByLabel('Подтверждаю восстановление входа раскадровки').check();const del=await fetch(BASE+'/api/visual-styles/'+style.id,{method:'DELETE',headers:{Cookie:cookie,'content-type':'application/json'},body:JSON.stringify({revision:style.revision})});assert.equal(del.status,200);await r.getByRole('button',{name:'Восстановить вход без генерации'}).click();await r.getByText(/Проект, снимок или доступность настроек изменились/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'МОЙ ТЕКУЩИЙ ЧЕРНОВИК');await close(p);});

async function openStoryboardPicker(p,f){
 await p.getByRole('button',{name:'Закрыть помощника'}).click();
 await p.evaluate(()=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:'НЕ МЕНЯТЬ МОЙ ЧЕРНОВИК',style:'universal',customStyle:'Сохранить стиль',imageModel:'midjourney',videoModel:'kling',clip:5})));
 await p.goto(BASE+'/storyboard');const box=p.getByLabel('Выбор сценария проекта для раскадровки');
 await box.getByLabel('Проект для выбора сценария').locator('option').filter({hasText:f.project.title}).waitFor({state:'attached'});
 return box;
}
async function chooseStoryboardPicker(box,f){await box.getByLabel('Проект для выбора сценария').selectOption(f.project.id);await box.getByLabel('Версия сценария из проекта').locator('option').filter({hasText:'Первая версия'}).waitFor({state:'attached'});await box.getByLabel('Версия сценария из проекта').selectOption(f.first.id);await box.getByRole('button',{name:'Сравнить выбранный сценарий'}).click();await box.getByText('Выбранный текст целиком').waitFor();}
test('storyboard picker: exact older version needs review and consent; settings preserved, no AI',async()=>{const f=await storyboardFixture(),p=await page(),n=calls().length,box=await openStoryboardPicker(p,f);await box.getByLabel('Проект для выбора сценария').selectOption(f.project.id);await box.getByLabel('Версия сценария из проекта').locator('option').filter({hasText:'Первая версия'}).waitFor({state:'attached'});assert.equal(await box.getByLabel('Версия сценария из проекта').inputValue(),'');assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ МЕНЯТЬ МОЙ ЧЕРНОВИК');await box.getByLabel('Версия сценария из проекта').selectOption(f.first.id);await box.getByRole('button',{name:'Сравнить выбранный сценарий'}).click();await box.getByText('Выбранный текст целиком').waitFor();assert.ok((await box.innerText()).includes(f.text.trim()));assert.equal(await box.getByRole('button',{name:'Применить выбранный сценарий'}).isDisabled(),true);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.scrollIntoViewIfNeeded();assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await p.screenshot({path:OUT+'/storyboard-picker-review-light.png'});await box.getByLabel('Подтверждаю выбор сценария проекта').check();await box.getByRole('button',{name:'Применить выбранный сценарий'}).click();await p.waitForFunction(t=>document.querySelector('textarea[aria-label="Сценарий"]')?.value===t,f.text);assert.equal(await p.getByPlaceholder('Например: тёмная акварель').inputValue(),'Сохранить стиль');assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);assert.equal(calls().length,n);await close(p);});
test('storyboard picker: cancellation and version changes never replace the draft',async()=>{const f=await storyboardFixture(),p=await page(),box=await openStoryboardPicker(p,f);await chooseStoryboardPicker(box,f);await box.getByLabel('Подтверждаю выбор сценария проекта').check();const options=box.getByLabel('Версия сценария из проекта');await options.selectOption({label:await options.locator('option').filter({hasText:'Поздняя версия'}).textContent()});assert.equal(await box.getByRole('button',{name:'Применить выбранный сценарий'}).count(),0);await box.getByRole('button',{name:'Отменить выбор сценария'}).click();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ МЕНЯТЬ МОЙ ЧЕРНОВИК');assert.equal(await box.getByLabel('Проект для выбора сценария').inputValue(),'');await close(p);});
test('storyboard picker: stale project blocks application',async()=>{const f=await storyboardFixture(),p=await page(),box=await openStoryboardPicker(p,f);await chooseStoryboardPicker(box,f);await box.getByLabel('Подтверждаю выбор сценария проекта').check();await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Параллельная правка',data:'KEEP'});await box.getByRole('button',{name:'Применить выбранный сценарий'}).click();await box.getByText(/Проект или сценарий изменились/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ МЕНЯТЬ МОЙ ЧЕРНОВИК');assert.equal(await box.getByLabel('Подтверждаю выбор сценария проекта').isChecked(),false);await close(p);});
test('storyboard picker: editing form invalidates consent',async()=>{const f=await storyboardFixture(),p=await page(),box=await openStoryboardPicker(p,f);await chooseStoryboardPicker(box,f);await box.getByLabel('Подтверждаю выбор сценария проекта').check();await p.getByPlaceholder('Например: тёмная акварель').fill('Новое оформление');await p.waitForFunction(()=>!document.querySelector('input[aria-label="Подтверждаю выбор сценария проекта"]').checked);assert.equal(await box.getByRole('button',{name:'Применить выбранный сценарий'}).isDisabled(),true);await close(p);});
test('storyboard picker: draft edit during recheck is not overwritten',async()=>{const f=await storyboardFixture(),p=await page(),box=await openStoryboardPicker(p,f);await chooseStoryboardPicker(box,f);await box.getByLabel('Подтверждаю выбор сценария проекта').check();let release,seen;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/storyboard-source-preview',async route=>{seen();await gate;await route.continue();});await box.getByRole('button',{name:'Применить выбранный сценарий'}).click();await started;await p.getByLabel('Сценарий',{exact:true}).fill('Правка во время проверки');release();await box.getByText(/Черновик или результат изменился во время проверки/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'Правка во время проверки');await close(p);});
test('storyboard picker: cancellation while recheck pending cannot apply late response',async()=>{const f=await storyboardFixture(),p=await page(),box=await openStoryboardPicker(p,f);await chooseStoryboardPicker(box,f);await box.getByLabel('Подтверждаю выбор сценария проекта').check();let release,seen;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/storyboard-source-preview',async route=>{seen();await gate;await route.continue();});await box.getByRole('button',{name:'Применить выбранный сценарий'}).click();await started;await box.getByRole('button',{name:'Отменить выбор сценария'}).click();release();await p.waitForTimeout(300);assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ МЕНЯТЬ МОЙ ЧЕРНОВИК');assert.equal(await box.getByRole('button',{name:'Применить выбранный сценарий'}).count(),0);await close(p);});
test('storyboard picker: too-short source cannot replace draft',async()=>{const f=await storyboardFixture(),short=(await(await req('/projects/'+f.project.id+'/artifacts',{kind:'script',title:'Короткий',data:{script:'Мало текста'}})).json()).data,p=await page(),box=await openStoryboardPicker(p,f);await box.getByLabel('Проект для выбора сценария').selectOption(f.project.id);await box.getByLabel('Версия сценария из проекта').locator('option').filter({hasText:'Короткий'}).waitFor({state:'attached'});await box.getByLabel('Версия сценария из проекта').selectOption(short.id);await box.getByRole('button',{name:'Сравнить выбранный сценарий'}).click();await box.getByText(/от 200 непустых до 60 000 символов/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ МЕНЯТЬ МОЙ ЧЕРНОВИК');assert.equal(await box.getByRole('button',{name:'Применить выбранный сценарий'}).count(),0);await close(p);});
test('storyboard picker: existing saved result stays through review and cancel; apply hides only screen copy',async()=>{const f=await savedStoryboardFixture(),p=await page(),n=calls().length,r=await openSaved(p,f,f.saved);await r.getByRole('button',{name:'Сравнить с черновиком'}).waitFor();const csv=p.getByRole('button',{name:'CSV',exact:true});await csv.waitFor();const box=p.getByLabel('Выбор сценария проекта для раскадровки');async function review(){await box.getByLabel('Проект для выбора сценария').locator('option').filter({hasText:f.project.title}).waitFor({state:'attached'});await box.getByLabel('Проект для выбора сценария').selectOption(f.project.id);const versions=box.getByLabel('Версия сценария из проекта');await versions.locator('option').filter({hasText:'Исходный'}).waitFor({state:'attached'});await versions.selectOption({label:await versions.locator('option').filter({hasText:'Исходный'}).textContent()});await box.getByRole('button',{name:'Сравнить выбранный сценарий'}).click();await box.getByText('Выбранный текст целиком').waitFor();}await review();assert.equal(await csv.isVisible(),true);await box.getByRole('button',{name:'Отменить выбор сценария'}).click();assert.equal(await csv.isVisible(),true);await review();await box.getByLabel('Подтверждаю выбор сценария проекта').check();await box.getByRole('button',{name:'Применить выбранный сценарий'}).click();await p.waitForFunction(t=>document.querySelector('textarea[aria-label="Сценарий"]')?.value===t,f.old);assert.equal(await csv.count(),0);const saved=(await(await req('/projects/'+f.project.id)).json()).data;assert.ok(saved.artifacts.some(a=>a.id===f.saved.id));assert.equal(saved.artifacts.length,4);assert.equal(calls().length,n);await close(p);});

async function editorStoryboardFixture(){const project=(await(await req('/projects',{title:'Редактор '+crypto.randomUUID().slice(0,6)})).json()).data;const original='Оригинал сценария. Ночной город и первые огни. '.repeat(8);const data={...JSON.parse(fs.readFileSync(ROOT+'/tests/e2e/fixtures/script.json','utf8')),title:'Исходный сценарий',script:original,projectId:project.id};const artifact=(await(await req('/projects/'+project.id+'/artifacts',{kind:'script',title:data.title,data})).json()).data;return {project,artifact,original};}
async function openScriptEditor(p,f){await p.getByRole('button',{name:'Закрыть помощника'}).click();await p.evaluate(()=>localStorage.setItem('ts:draft:storyboard',JSON.stringify({script:'НЕ ЗАТИРАТЬ ЧЕРНОВИК',style:'universal',customStyle:'Текущий стиль',imageModel:'midjourney',videoModel:'kling',clip:5})));await p.goto(BASE+'/script?projectId='+f.project.id+'&artifact='+f.artifact.id);const input=p.getByLabel('Текст сценария');await input.waitFor();await p.waitForFunction(t=>document.querySelector('textarea[aria-label="Текст сценария"]')?.value===t,f.original);await p.getByRole('button',{name:'В раскадровку ↗'}).waitFor();return input;}
async function sendEditorToStoryboard(p){const next=p.waitForEvent('popup');await p.getByRole('button',{name:'В раскадровку ↗'}).click();const q=await next;q.errors=[];q.on('pageerror',e=>q.errors.push(e.message));await q.waitForLoadState('domcontentloaded');const box=q.getByLabel('Передача из редактора сценария');await box.getByText('Переданный текст целиком').waitFor();return {q,box};}
test('editor storyboard transfer: edited exact text to new tab, explicit apply, source editor remains',async()=>{const f=await editorStoryboardFixture(),p=await page(),input=await openScriptEditor(p,f),edited='РЕДАКТИРОВАННЫЙ СЦЕНАРИЙ. Город оживает.\n'.repeat(9),n=calls().length;await input.fill(edited);const {q,box}=await sendEditorToStoryboard(p);assert.match(await box.innerText(),/отличающийся от открытого результата/);assert.ok((await box.innerText()).includes(edited.trim()));assert.equal(await q.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ ЗАТИРАТЬ ЧЕРНОВИК');assert.equal(await box.getByRole('button',{name:'Применить текст из редактора'}).isDisabled(),true);assert.equal(await p.evaluate(()=>Object.keys(sessionStorage).some(k=>k.startsWith('ts:storyboard-editor-transfer:'))),false);assert.equal(await q.evaluate(()=>Object.keys(sessionStorage).some(k=>k.startsWith('ts:storyboard-editor-transfer:'))),false);await q.setViewportSize({width:1024,height:900});await q.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.scrollIntoViewIfNeeded();assert.equal(await q.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await q.screenshot({path:OUT+'/storyboard-editor-transfer-light.png'});await box.getByLabel('Подтверждаю текст из редактора').check();await box.getByRole('button',{name:'Применить текст из редактора'}).click();await q.waitForFunction(t=>document.querySelector('textarea[aria-label="Сценарий"]')?.value===t,edited);assert.equal(await q.getByPlaceholder('Например: тёмная акварель').inputValue(),'Текущий стиль');assert.equal(await input.inputValue(),edited);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);assert.equal(calls().length,n);assert.deepEqual(q.errors,[]);await close(p);});
test('editor storyboard transfer: cancel preserves both tabs',async()=>{const f=await editorStoryboardFixture(),p=await page(),input=await openScriptEditor(p,f),edited='Новое содержание. '.repeat(18);await input.fill(edited);const {q,box}=await sendEditorToStoryboard(p);await box.getByRole('button',{name:'Отменить передачу из редактора'}).click();assert.equal(await q.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ ЗАТИРАТЬ ЧЕРНОВИК');assert.equal(await input.inputValue(),edited);assert.deepEqual(q.errors,[]);await close(p);});
test('editor storyboard transfer: frozen copy and changed destination resets consent',async()=>{const f=await editorStoryboardFixture(),p=await page(),input=await openScriptEditor(p,f),first='Первый замороженный текст. '.repeat(12),second='Поздняя правка редактора. '.repeat(12);await input.fill(first);const {q,box}=await sendEditorToStoryboard(p);await input.fill(second);assert.ok((await box.innerText()).includes(first.trim()));assert.equal((await box.innerText()).includes(second.trim()),false);await box.getByLabel('Подтверждаю текст из редактора').check();await q.getByLabel('Сценарий',{exact:true}).fill('Новый текущий черновик');await q.waitForFunction(()=>!document.querySelector('input[aria-label="Подтверждаю текст из редактора"]').checked);assert.equal(await box.getByRole('button',{name:'Применить текст из редактора'}).isDisabled(),true);assert.equal(await input.inputValue(),second);assert.deepEqual(q.errors,[]);await close(p);});
test('editor storyboard transfer: popup blocking keeps editor and clears temporary data',async()=>{const f=await editorStoryboardFixture(),p=await page(),input=await openScriptEditor(p,f);await p.evaluate(()=>{window.open=()=>null;});await p.getByRole('button',{name:'В раскадровку ↗'}).click();await p.getByText(/Не удалось открыть вкладку раскадровки/).waitFor();assert.equal(await input.inputValue(),f.original);assert.equal(await p.evaluate(()=>Object.keys(sessionStorage).some(k=>k.startsWith('ts:storyboard-editor-transfer:'))),false);await close(p);});
test('editor storyboard transfer: size limits reject without truncation or opening tab',async()=>{const f=await editorStoryboardFixture(),p=await page(),input=await openScriptEditor(p,f);await input.fill('A'.repeat(199));await p.getByRole('button',{name:'В раскадровку ↗'}).click();await p.getByText(/от 200 непустых до 60 000 символов/).waitFor();assert.equal((await input.inputValue()).length,199);await input.fill('B'.repeat(60001));await p.getByRole('button',{name:'В раскадровку ↗'}).click();await p.getByText(/от 200 непустых до 60 000 символов/).waitFor();assert.equal((await input.inputValue()).length,60001);assert.equal(p.context().pages().length,1);await close(p);});
test('editor storyboard transfer: storage refusal retains source and never opens tab',async()=>{const f=await editorStoryboardFixture(),p=await page(),input=await openScriptEditor(p,f);await p.evaluate(()=>{const orig=Storage.prototype.setItem;Storage.prototype.setItem=function(k,v){if(this===sessionStorage&&k.startsWith('ts:storyboard-editor-transfer:'))throw new Error('quota');return orig.call(this,k,v);};});await p.getByRole('button',{name:'В раскадровку ↗'}).click();await p.getByText(/Не удалось подготовить временную передачу/).waitFor();assert.equal(await input.inputValue(),f.original);assert.equal(p.context().pages().length,1);await close(p);});
test('editor storyboard transfer: reload loses pending copy and unrelated handoff is not consumed',async()=>{const f=await editorStoryboardFixture(),p=await page();await openScriptEditor(p,f);await p.evaluate(()=>sessionStorage.setItem('ts:handoff',JSON.stringify({text:'ДРУГОЙ МОДУЛЬ НЕ ТРОГАТЬ'})));const {q}=await sendEditorToStoryboard(p);await q.reload();await q.getByText(/Временная передача недоступна или уже использована/).waitFor();assert.equal(await q.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ ЗАТИРАТЬ ЧЕРНОВИК');assert.match(await q.evaluate(()=>sessionStorage.getItem('ts:handoff')),/ДРУГОЙ МОДУЛЬ/);assert.deepEqual(q.errors,[]);await close(p);});
test('editor storyboard transfer: invalid token never changes draft',async()=>{const f=await editorStoryboardFixture(),p=await page();await openScriptEditor(p,f);await p.goto(BASE+'/storyboard?editorTransfer=bad-token');await p.getByText(/Временная передача недоступна или уже использована/).waitFor();assert.equal(await p.getByLabel('Сценарий',{exact:true}).inputValue(),'НЕ ЗАТИРАТЬ ЧЕРНОВИК');assert.equal(await p.getByRole('button',{name:'Применить текст из редактора'}).count(),0);await close(p);});
test('editor storyboard transfer: repeated clicks create independent frozen copies without text in URLs',async()=>{const f=await editorStoryboardFixture(),p=await page(),input=await openScriptEditor(p,f),a='ПЕРВЫЙ ТЕКСТ. '.repeat(20),b='ВТОРОЙ ТЕКСТ. '.repeat(20);await input.fill(a);const one=await sendEditorToStoryboard(p);await input.fill(b);const two=await sendEditorToStoryboard(p);assert.ok((await one.box.innerText()).includes(a.trim()));assert.ok((await two.box.innerText()).includes(b.trim()));assert.notEqual(one.q.url(),two.q.url());assert.equal(one.q.url().includes(encodeURIComponent(a)),false);assert.equal(two.q.url().includes(encodeURIComponent(b)),false);assert.equal(await input.inputValue(),b);assert.deepEqual(one.q.errors,[]);assert.deepEqual(two.q.errors,[]);await close(p);});

async function contextBoardFixture(){const project=(await(await req('/projects',{title:'Сцены '+crypto.randomUUID().slice(0,6)})).json()).data;const row=n=>({n,text:'Речь '+n,concept:'Сюжет '+n,image:'IMAGE PROMPT '+n+' with precise details',video:'VIDEO PROMPT '+n+' smooth motion'});const first=(await(await req('/projects/'+project.id+'/artifacts',{kind:'storyboard',title:'Старые сцены',data:{rows:[row(3),row(8),row(5)],done:false,input:{script:'ПОЛНЫЙ ТЕКСТ НЕ ДЛЯ КОНТЕКСТА'},bible:{medium:'SECRET_BIBLE'}}})).json()).data;await req('/projects/'+project.id+'/artifacts',{kind:'storyboard',title:'Поздняя раскадровка',data:{rows:[row(12)],done:true}});return {project,first};}
async function contextBoardPicker(p,f){const box=p.getByLabel('Сцены раскадровки для помощника');await box.getByRole('button',{name:'Выбрать сцены для диалога'}).click();await box.getByLabel('Проект раскадровки для помощника').selectOption(f.project.id);await box.getByLabel('Раскадровка для помощника').locator('option').filter({hasText:'Старые сцены'}).waitFor({state:'attached'});await box.getByLabel('Раскадровка для помощника').selectOption(f.first.id);return box;}
async function previewBoardContext(box,from='1',to='2'){await box.getByLabel('Первая позиция сцены').fill(from);await box.getByLabel('Последняя позиция сцены').fill(to);await box.getByRole('button',{name:'Проверить выбранные сцены'}).click();await box.getByText('Полная копия для диалога').waitFor();}
test('assistant storyboard context: selected exact scenes, consent, new dialogue and author preview without AI',async()=>{const f=await contextBoardFixture(),p=await page(),n=calls().length,box=await contextBoardPicker(p,f);assert.equal(await box.getByLabel('Раскадровка для помощника').inputValue(),f.first.id);await previewBoardContext(box);const text=await box.innerText();assert.match(text,/IMAGE PROMPT 3/);assert.match(text,/VIDEO PROMPT 8/);assert.doesNotMatch(text,/IMAGE PROMPT 5|SECRET_BIBLE|ПОЛНЫЙ ТЕКСТ/);assert.equal(await box.getByRole('button',{name:'Добавить сцены в материалы'}).isDisabled(),true);assert.equal(await p.getByRole('button',{name:'Создать локальный диалог'}).isDisabled(),true);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.scrollIntoViewIfNeeded();assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await p.screenshot({path:OUT+'/assistant-board-context-light.png'});await box.getByLabel('Подтверждаю выбранные сцены').check();await box.getByRole('button',{name:'Добавить сцены в материалы'}).click();await p.getByText(/storyboard-.*\.txt · .* символов/).waitFor();await create(p);const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),run=(await(await req('/assistant/conversations/'+id)).json()).data;assert.equal(run.context.documents.length,1);const saved=JSON.parse(run.context.documents[0].text);assert.deepEqual(saved.rows.map(x=>x.n),[3,8]);assert.equal(saved.storyboardId,f.first.id);assert.equal(calls().length,n);const ask={id,question:'Проверь промпты изображений',task:'imagePrompt',currentPath:'/storyboard',attemptId:crypto.randomUUID()},preview=(await(await req('/assistant/preview',ask)).json()).data;const payload=JSON.parse(preview.user);assert.deepEqual(payload.context.documents,run.context.documents);assert.equal(preview.selection.model,'fixture-author');assert.equal(calls().length,n);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);await close(p);});
test('assistant storyboard context: cancellation and changed range clear review and consent',async()=>{const f=await contextBoardFixture(),p=await page(),box=await contextBoardPicker(p,f);await previewBoardContext(box);await box.getByLabel('Подтверждаю выбранные сцены').check();await box.getByLabel('Последняя позиция сцены').fill('3');assert.equal(await box.getByRole('button',{name:'Добавить сцены в материалы'}).count(),0);await box.getByRole('button',{name:'Отменить выбор сцен'}).click();assert.equal(await p.getByRole('button',{name:'Создать локальный диалог'}).isEnabled(),true);await create(p);const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));assert.deepEqual((await(await req('/assistant/conversations/'+id)).json()).data.context.documents,[]);await close(p);});
