test('assistant storyboard context HTTP: auth, origin, strict input, bounds, missing or unsafe record',async()=>{const f=await contextBoardFixture(),ask={projectId:f.project.id,artifactId:f.first.id,from:1,to:2},n=calls().length;assert.equal((await req('/assistant/storyboard-excerpt-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/storyboard-excerpt-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);for(const bad of [{...ask,text:'inject'},{...ask,from:0},{...ask,to:101}])assert.equal((await req('/assistant/storyboard-excerpt-preview',bad)).status,400);assert.equal((await req('/assistant/storyboard-excerpt-preview',{...ask,to:4})).status,409);const v=(await(await req('/assistant/storyboard-excerpt-preview',ask)).json()).data;assert.deepEqual(JSON.parse(v.document.text).rows.map(r=>r.n),[3,8]);assert.equal(calls().length,n);});
test('assistant storyboard context: explicit author request sends only copied scenes to synthetic model',async()=>{const f=await contextBoardFixture(),p=await page(),n=compatibleCalls.length;await addConnection(p,'Автор для сцен');const box=await contextBoardPicker(p,f);await previewBoardContext(box,'2','3');await box.getByLabel('Подтверждаю выбранные сцены').check();await box.getByRole('button',{name:'Добавить сцены в материалы'}).click();await p.getByText(/storyboard-.*\.txt · .* символов/).waitFor();await p.getByLabel('Название задачи помощника').fill('Работа со сценами');await pickConnection(p,'Авторская модель','Автор для сцен','scene-author');await pickConnection(p,'Рутинная модель','Автор для сцен','scene-routine');await p.getByRole('button',{name:'Создать локальный диалог'}).click();await p.getByLabel('Сообщение помощнику').waitFor();await p.getByLabel('Роль модели помощника').selectOption('imagePrompt');await p.getByLabel('Сообщение помощнику').fill('Уточни промпты выбранных сцен без добавления фактов.');await p.getByRole('button',{name:'Проверить перед отправкой'}).click();assert.equal(compatibleCalls.length,n);await p.getByRole('button',{name:'Подтвердить и отправить в AI'}).click();await p.getByText('Ответ независимого сервиса.').waitFor();assert.equal(compatibleCalls.length,n+1);assert.equal(compatibleCalls.at(-1).body.model,'scene-author');const user=JSON.parse(compatibleCalls.at(-1).body.messages[1].content),document=JSON.parse(user.context.documents[0].text);assert.deepEqual(document.rows.map(x=>x.n),[8,5]);assert.equal(document.rows[0].image,'IMAGE PROMPT 8 with precise details');assert.equal(JSON.stringify(document).includes('SECRET_BIBLE'),false);await close(p);});

async function revisionFixture(){const project=(await(await req('/projects',{title:'Правка '+crypto.randomUUID().slice(0,6)})).json()).data;const row=n=>({n,text:`Точный текст ${n}`,concept:`Концепт ${n}`,image:`СТАРЫЙ IMAGE ${n}`,video:`СТАРЫЙ VIDEO ${n}`,words:2,seconds:5,start:n*5,clip:5,clips:1,batch:1});const first=(await(await req('/projects/'+project.id+'/artifacts',{kind:'storyboard',title:'Исходная',data:{rows:[row(7),row(8)],bible:{medium:'photo',palette:'x',lighting:'x',camera:'x',mood:'x',negative:'x',characters:[],locations:[]},batches:[{n:1,from:1,to:2,errors:[],warnings:[],retried:false}],totalUnits:2,totalSeconds:10,done:true,model:'fixture',input:{script:'исходный сценарий'}}})).json()).data;return {project,first};}
