test('storyboard prompt revision: compare, explicit save as new version, no AI and validator warning',async()=>{const f=await revisionFixture(),n=calls().length,{p,box}=await revisionUI(f);assert.equal(await box.getByLabel('Новый image-промпт').inputValue(),'СТАРЫЙ IMAGE 8');await box.getByLabel('Новый image-промпт').fill('НОВЫЙ IMAGE ИЗ ПОМОЩНИКА\nточно');await box.getByLabel('Новый video-промпт').fill('НОВЫЙ VIDEO');await box.getByRole('button',{name:'Сравнить правки'}).click();await box.getByText('СТАРЫЙ IMAGE 8',{exact:true}).waitFor();assert.equal(await box.getByRole('button',{name:'Сохранить новую версию'}).isDisabled(),true);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByText('SHA-256 проверки:',{exact:false}).scrollIntoViewIfNeeded();await p.screenshot({path:OUT+'/storyboard-prompt-revision-light.png'});await box.getByLabel('Подтверждаю правку промптов').check();await box.getByRole('button',{name:'Сохранить новую версию'}).click();await box.getByText(/Версия v2 сохранена/).waitFor();const project=(await(await req('/projects/'+f.project.id)).json()).data;assert.deepEqual(project.artifacts[0],f.first);const added=project.artifacts[1];assert.equal(added.data.rows[1].image,'НОВЫЙ IMAGE ИЗ ПОМОЩНИКА\nточно');assert.equal(added.data.rows[1].video,'НОВЫЙ VIDEO');assert.equal(added.data.rows[0].image,'СТАРЫЙ IMAGE 7');assert.equal(added.data.manualPromptRevision.sourceArtifactId,f.first.id);assert.equal(calls().length,n);await box.getByRole('link',{name:'Открыть новую версию'}).click();await p.getByText(/Ручная правка промптов позиции 2/).waitFor();assert.equal(await p.getByText(/Все батчи прошли валидаторы/).count(),0);assert.deepEqual(p.errors,[]);await close(p);});
test('storyboard prompt revision: changes invalidate review and stale source blocks write',async()=>{const f=await revisionFixture(),{p,box}=await revisionUI(f);await box.getByLabel('Новый image-промпт').fill('ПРАВКА 1');await box.getByRole('button',{name:'Сравнить правки'}).click();await box.getByLabel('Подтверждаю правку промптов').check();await box.getByLabel('Новый image-промпт').fill('ПРАВКА 2');assert.equal(await box.getByLabel('Подтверждаю правку промптов').count(),0);await box.getByRole('button',{name:'Сравнить правки'}).click();await box.getByLabel('Подтверждаю правку промптов').check();await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Чужое изменение',data:'сохранить'});await box.getByRole('button',{name:'Сохранить новую версию'}).click();await box.getByText(/Проект изменился после загрузки сцены/).waitFor();assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);assert.equal(await box.getByLabel('Подтверждаю правку промптов').isChecked(),false);await close(p);});
