test('assistant prompt to scene: closing during confirmed save does not pretend to cancel',async()=>{const f=await revisionFixture(),{p,box}=await promptSceneUI(f);await box.getByLabel('Поле промпта сцены').selectOption('image');await box.getByRole('button',{name:'Сравнить промпты сцены'}).click();await box.getByText(/сохранение может завершиться даже при закрытии панели/).waitFor();await box.getByLabel('Подтверждаю ответ для сцены').check();let release,seen;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/storyboard-prompt-revision',async route=>{seen();await gate;await route.continue();});await box.getByRole('button',{name:'Сохранить ответ новой версией'}).click();await started;await p.getByRole('button',{name:'Закрыть помощника'}).click();release();await p.waitForFunction(async id=>{const r=await fetch('/api/projects/'+id);const j=await r.json();return j.data?.artifacts?.length===2;},f.project.id);const a=(await(await req('/projects/'+f.project.id)).json()).data.artifacts;assert.equal(a.length,2);assert.deepEqual(a[0],f.first);assert.equal(a[1].data.rows[1].image,'АВТОРСКИЕ ПРОМПТЫ: городской пейзаж на рассвете.');await close(p);});

async function promptBatchUI(f){const p=await page();await create(p);await p.getByLabel('Роль модели помощника').selectOption('imagePrompt');await send(p,'Подготовь промпты для нескольких сцен.');const box=p.getByLabel('Пакет промптов из ответа');await box.getByRole('button',{name:'Подготовить пакет сцен'}).click();await box.getByLabel('Проект пакета сцен').selectOption(f.project.id);await box.getByLabel('Раскадровка пакета сцен').locator('option').filter({hasText:'Исходная'}).waitFor({state:'attached'});await box.getByLabel('Раскадровка пакета сцен').selectOption(f.first.id);return {p,box};}
async function stageBatch(box,position,field,text){await box.getByLabel('Позиция сцены в пакете').fill(String(position));await box.getByRole('button',{name:'Загрузить сцену для пакета'}).click();await box.getByLabel('Поле сцены в пакете').selectOption(field);await box.getByLabel('Текст сцены в пакете').fill(text);await box.getByRole('button',{name:'Добавить сцену в пакет'}).click();await box.getByRole('button',{name:`Убрать позицию ${position} · ${field.toUpperCase()}`,exact:true}).waitFor();}
test('assistant prompt batch: two explicit mappings, full review, one new version and no extra AI',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f),n=calls().length;await stageBatch(box,1,'image','новый IMAGE сцены один');await stageBatch(box,2,'video','новый VIDEO сцены два');await box.getByRole('button',{name:'Сравнить весь пакет'}).click();await box.getByText('СТАРЫЙ IMAGE 7',{exact:true}).waitFor();await box.getByText('СТАРЫЙ VIDEO 8',{exact:true}).waitFor();assert.equal(await box.getByRole('button',{name:'Сохранить пакет одной версией'}).isDisabled(),true);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByText('SHA-256 проверки:',{exact:false}).scrollIntoViewIfNeeded();await p.screenshot({path:OUT+'/assistant-prompt-batch-light.png'});await box.getByLabel('Подтверждаю весь пакет сцен').check();await box.getByRole('button',{name:'Сохранить пакет одной версией'}).click();await box.getByText(/Версия v2 сохранена/).waitFor();const project=(await(await req('/projects/'+f.project.id)).json()).data;assert.equal(project.artifacts.length,2);assert.deepEqual(project.artifacts[0],f.first);const d=project.artifacts[1].data;assert.equal(d.rows[0].image,'новый IMAGE сцены один');assert.equal(d.rows[0].video,'СТАРЫЙ VIDEO 7');assert.equal(d.rows[1].image,'СТАРЫЙ IMAGE 8');assert.equal(d.rows[1].video,'новый VIDEO сцены два');assert.deepEqual(d.manualPromptRevision.positions,[1,2]);assert.equal(calls().length,n);assert.equal(await p.getByRole('dialog').evaluate(e=>e.scrollWidth>e.clientWidth),false);await box.getByRole('link',{name:'Открыть версию пакета'}).click();await p.getByRole('button',{name:'Закрыть помощника'}).click();await p.getByText(/Ручная правка промптов позиций 1, 2/).waitFor();assert.equal(await p.getByText(/Все батчи прошли валидаторы/).count(),0);await close(p);});
test('assistant prompt batch: explicit field, duplicate position-field pair, removal and consent reset',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await box.getByRole('button',{name:'Загрузить сцену для пакета'}).click();assert.equal(await box.getByLabel('Поле сцены в пакете').inputValue(),'');assert.equal(await box.getByRole('button',{name:'Добавить сцену в пакет'}).isDisabled(),true);await box.getByLabel('Поле сцены в пакете').selectOption('image');await box.getByLabel('Текст сцены в пакете').fill('первый');await box.getByRole('button',{name:'Добавить сцену в пакет'}).click();await box.getByRole('button',{name:'Загрузить сцену для пакета'}).click();await box.getByLabel('Поле сцены в пакете').selectOption('image');await box.getByRole('button',{name:'Добавить сцену в пакет'}).click();await box.getByText(/Это поле позиции уже в пакете/).waitFor();await box.getByRole('button',{name:'Сравнить весь пакет'}).click();await box.getByLabel('Подтверждаю весь пакет сцен').check();await box.getByRole('button',{name:'Убрать позицию 1 · IMAGE'}).click();assert.equal(await box.getByLabel('Подтверждаю весь пакет сцен').count(),0);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await close(p);});
test('assistant prompt batch: changed project blocks adding further scene and saving staged edits',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await stageBatch(box,1,'image','правка один');await box.getByRole('button',{name:'Сравнить весь пакет'}).click();await box.getByLabel('Подтверждаю весь пакет сцен').check();await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Изменение',data:'keep'});await box.getByRole('button',{name:'Сохранить пакет одной версией'}).click();await box.getByText(/Проект изменился после загрузки сцен/).waitFor();assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);await box.getByLabel('Позиция сцены в пакете').fill('2');await box.getByRole('button',{name:'Загрузить сцену для пакета'}).click();await box.getByText(/Проект изменился после загрузки сцен/).waitFor();await box.getByRole('button',{name:'Сбросить пакет сцен'}).click();assert.equal(await box.getByRole('button',{name:'Сравнить весь пакет'}).count(),0);await close(p);});
test('assistant prompt batch: oversize and empty values block staging without truncation',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await box.getByRole('button',{name:'Загрузить сцену для пакета'}).click();await box.getByLabel('Поле сцены в пакете').selectOption('image');const text=box.getByLabel('Текст сцены в пакете'),button=box.getByRole('button',{name:'Добавить сцену в пакет'});await text.fill('A'.repeat(10001));assert.equal((await text.inputValue()).length,10001);assert.equal(await button.isDisabled(),true);await text.fill('  ');assert.equal(await button.isDisabled(),true);await text.fill('подходящий фрагмент');assert.equal(await button.isEnabled(),true);await box.getByRole('button',{name:'Скрыть пакет промптов'}).click();assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await close(p);});
test('assistant prompt batch: audio source and invalid position cannot create version',async()=>{const f=await revisionFixture(),audio=(await(await req('/projects/'+f.project.id+'/artifacts',{kind:'storyboard',title:'Звуковая',data:{source:'audio',rows:[{n:1,text:'x',concept:'x',image:'x',video:'x'}]}})).json()).data,{p,box}=await promptBatchUI(f);await box.getByLabel('Раскадровка пакета сцен').selectOption(audio.id);assert.equal(await box.getByRole('button',{name:'Загрузить сцену для пакета'}).isDisabled(),true);await box.getByLabel('Раскадровка пакета сцен').selectOption(f.first.id);await box.getByLabel('Позиция сцены в пакете').fill('9');await box.getByRole('button',{name:'Загрузить сцену для пакета'}).click();await box.getByText(/выходит за список сохранённых сцен/).waitFor();assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);await close(p);});
test('assistant prompt batch HTTP: auth, origin, strict schema, confirmation and replay',async()=>{const f=await revisionFixture(),x=(await(await req('/assistant/storyboard-excerpt-preview',{projectId:f.project.id,artifactId:f.first.id,from:1,to:1})).json()).data,ask={projectId:f.project.id,artifactId:f.first.id,title:'Пакет',actionId:crypto.randomUUID(),sourceSnapshot:x.projectSnapshot,entries:[{position:1,field:'image',value:'новое'}, {position:2,field:'video',value:'движение'}]};assert.equal((await req('/assistant/storyboard-prompt-batch-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/storyboard-prompt-batch-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);assert.equal((await req('/assistant/storyboard-prompt-batch-preview',{...ask,entries:[ask.entries[0],ask.entries[0]]})).status,400);assert.equal((await req('/assistant/storyboard-prompt-batch-preview',{...ask,extra:true})).status,400);const v=(await(await req('/assistant/storyboard-prompt-batch-preview',ask)).json()).data;assert.equal((await req('/assistant/storyboard-prompt-batch',{...ask,previewHash:v.hash,confirmed:false})).status,400);const body={...ask,previewHash:v.hash,confirmed:true};assert.equal((await req('/assistant/storyboard-prompt-batch',body)).status,200);assert.equal((await req('/assistant/storyboard-prompt-batch',body)).status,409);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);});
test('assistant prompt batch: confirmed save may finish after closing panel',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await stageBatch(box,1,'video','движение');await stageBatch(box,2,'image','кадр');await box.getByRole('button',{name:'Сравнить весь пакет'}).click();await box.getByText(/сохранение может завершиться даже при закрытии панели/).waitFor();await box.getByLabel('Подтверждаю весь пакет сцен').check();let release,seen;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/storyboard-prompt-batch',async route=>{seen();await gate;await route.continue();});await box.getByRole('button',{name:'Сохранить пакет одной версией'}).click();await started;await p.getByRole('button',{name:'Закрыть помощника'}).click();release();await p.waitForFunction(async id=>{const r=await fetch('/api/projects/'+id),j=await r.json();return j.data?.artifacts?.length===2;},f.project.id);const a=(await(await req('/projects/'+f.project.id)).json()).data.artifacts;assert.equal(a.length,2);assert.deepEqual(a[0],f.first);assert.equal(a[1].data.rows[0].video,'движение');assert.equal(a[1].data.rows[1].image,'кадр');await close(p);});


test('assistant prompt batch dual: two fields in one position reviewed and committed together',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f),n=calls().length;await stageBatch(box,1,'image','новый кадр');await stageBatch(box,1,'video','новое движение');await stageBatch(box,2,'image','другой кадр');await box.getByText(/2\/20 позиций · 3\/40 полей/).waitFor();await box.getByRole('button',{name:'Сравнить весь пакет'}).click();await box.getByText(/Позиция 1 · номер 7 · IMAGE \+ VIDEO/).waitFor();await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByText(/Позиция 1 · номер 7 · IMAGE \+ VIDEO/).scrollIntoViewIfNeeded();await p.screenshot({path:OUT+'/assistant-prompt-batch-dual-light.png'});await box.getByLabel('Подтверждаю весь пакет сцен').check();await box.getByRole('button',{name:'Сохранить пакет одной версией'}).click();await box.getByText(/Версия v2 сохранена/).waitFor();const a=(await(await req('/projects/'+f.project.id)).json()).data.artifacts;assert.equal(a.length,2);assert.deepEqual(a[0],f.first);assert.equal(a[1].data.rows[0].image,'новый кадр');assert.equal(a[1].data.rows[0].video,'новое движение');assert.equal(a[1].data.rows[1].image,'другой кадр');assert.equal(a[1].data.rows[1].video,'СТАРЫЙ VIDEO 8');assert.deepEqual(a[1].data.manualPromptRevision.positions,[1,2]);assert.equal(calls().length,n);await close(p);});
test('assistant prompt batch dual: remove only one field and invalidate prior approval',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await stageBatch(box,1,'image','кадр');await stageBatch(box,1,'video','движение');await box.getByRole('button',{name:'Сравнить весь пакет'}).click();await box.getByLabel('Подтверждаю весь пакет сцен').check();await box.getByRole('button',{name:'Убрать позицию 1 · IMAGE'}).click();assert.equal(await box.getByLabel('Подтверждаю весь пакет сцен').count(),0);await box.getByText(/1\/20 позиций · 1\/40 полей/).waitFor();await box.getByRole('button',{name:'Сравнить весь пакет'}).click();await box.getByText(/Позиция 1 · номер 7 · VIDEO/).waitFor();await box.getByLabel('Подтверждаю весь пакет сцен').check();await box.getByRole('button',{name:'Сохранить пакет одной версией'}).click();await box.getByText(/Версия v2 сохранена/).waitFor();const a=(await(await req('/projects/'+f.project.id)).json()).data.artifacts;assert.equal(a[1].data.rows[0].image,'СТАРЫЙ IMAGE 7');assert.equal(a[1].data.rows[0].video,'движение');await close(p);});

test('assistant JSON candidate: synthetic author result -> exact review -> one explicit version',async()=>{const f=await revisionFixture(),p=await page();await create(p);await p.getByLabel('Роль модели помощника').selectOption('imagePrompt');await send(p,'СИНТЕТИЧЕСКИЙ JSON СЦЕН');const n=calls().length,box=p.getByLabel('Пакет промптов из ответа');await box.getByRole('button',{name:'Подготовить пакет сцен'}).click();await box.getByLabel('Проект пакета сцен').selectOption(f.project.id);await box.getByLabel('Раскадровка пакета сцен').locator('option').filter({hasText:'Исходная'}).waitFor({state:'attached'});await box.getByLabel('Раскадровка пакета сцен').selectOption(f.first.id);await box.getByRole('button',{name:'Открыть JSON-кандидат'}).click();await box.getByRole('button',{name:'Взять текущий ответ целиком'}).click();assert.deepEqual(JSON.parse(await box.getByLabel('JSON-кандидат сцен').inputValue()),[[1,'image','КАДР JSON'],[1,'video','ДВИЖЕНИЕ JSON'],[2,'image','ВТОРОЙ КАДР JSON']]);await box.getByRole('button',{name:'Разобрать JSON и сравнить'}).click();await box.getByText(/Позиция 1 · номер 7 · IMAGE \+ VIDEO/).waitFor();assert.equal(await box.getByRole('button',{name:'Сохранить пакет одной версией'}).isDisabled(),true);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByText(/Позиция 1 · номер 7 · IMAGE \+ VIDEO/).scrollIntoViewIfNeeded();await shot(p,'assistant-json-candidate-light');await box.getByLabel('Подтверждаю весь пакет сцен').check();await box.getByRole('button',{name:'Сохранить пакет одной версией'}).click();await box.getByText(/Версия v2 сохранена/).waitFor();const a=(await(await req('/projects/'+f.project.id)).json()).data.artifacts;assert.deepEqual(a[0],f.first);assert.equal(a.length,2);assert.equal(a[1].data.rows[0].image,'КАДР JSON');assert.equal(a[1].data.rows[0].video,'ДВИЖЕНИЕ JSON');assert.equal(a[1].data.rows[1].image,'ВТОРОЙ КАДР JSON');assert.equal(a[1].data.rows[1].video,'СТАРЫЙ VIDEO 8');assert.equal(calls().length,n);await close(p);});
test('assistant JSON candidate: invalid or ambiguous JSON leaves package and project unchanged',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f),n=calls().length;await box.getByRole('button',{name:'Открыть JSON-кандидат'}).click();const area=box.getByLabel('JSON-кандидат сцен');await area.fill('```json\n[[1,"image","x"]]\n```');await box.getByRole('button',{name:'Разобрать JSON и сравнить'}).click();await box.getByText(/Нужен только корректный JSON-массив/).waitFor();await area.fill('[[1,"image","a"],[1,"image","b"]]');await box.getByRole('button',{name:'Разобрать JSON и сравнить'}).click();await box.getByText(/Пара позиции и поля повторяется/).waitFor();assert.equal(await box.getByRole('button',{name:'Сохранить пакет одной версией'}).count(),0);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);assert.equal(calls().length,n);await close(p);});
test('assistant JSON candidate: missing later scene rejects whole preview without partial staging',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await box.getByRole('button',{name:'Открыть JSON-кандидат'}).click();await box.getByLabel('JSON-кандидат сцен').fill('[[1,"image","кадр"],[99,"video","движение"]]');await box.getByRole('button',{name:'Разобрать JSON и сравнить'}).click();await box.getByText(/Позиция 99 отсутствует или повреждена/).waitFor();assert.equal(await box.getByRole('button',{name:'Сравнить весь пакет'}).count(),0);assert.equal(await box.getByLabel('JSON-кандидат сцен').isEnabled(),true);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await close(p);});
test('assistant JSON candidate: manual staging cannot be silently replaced, reset unlocks import',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await stageBatch(box,1,'image','ручная правка');await box.getByRole('button',{name:'Открыть JSON-кандидат'}).click();assert.equal(await box.getByLabel('JSON-кандидат сцен').isDisabled(),true);assert.equal(await box.getByRole('button',{name:'Разобрать JSON и сравнить'}).isDisabled(),true);await box.getByRole('button',{name:'Сбросить пакет сцен'}).click();await box.getByLabel('JSON-кандидат сцен').fill('[[2,"video","новое движение"]]');await box.getByRole('button',{name:'Разобрать JSON и сравнить'}).click();await box.getByText(/Позиция 2 · номер 8 · VIDEO/).waitFor();assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await close(p);});
test('assistant JSON candidate: formatting request appends without sending or changing model',async()=>{const p=await page();await create(p);await p.getByLabel('Роль модели помощника').selectOption('animationPrompt');const n=calls().length,input=p.getByLabel('Сообщение помощнику');await input.fill('Моя задача: бережная анимация.');await p.getByRole('button',{name:'Добавить формат JSON сцен к сообщению'}).click();const text=await input.inputValue();assert.ok(text.startsWith('Моя задача: бережная анимация.'));assert.match(text,/не придумывай позиции/);assert.match(text,/\[\[1,"image"/);assert.equal(await p.getByLabel('Роль модели помощника').inputValue(),'animationPrompt');assert.equal(calls().length,n);await close(p);});

test('assistant JSON candidate: project changes between source and preview refuse whole candidate',async()=>{const f=await revisionFixture(),{p,box}=await promptBatchUI(f);await box.getByRole('button',{name:'Открыть JSON-кандидат'}).click();await box.getByLabel('JSON-кандидат сцен').fill('[[1,"image","новый кадр"],[2,"video","новое движение"]]');let intercepted=false;await p.route('**/api/assistant/storyboard-prompt-batch-preview',async route=>{intercepted=true;await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Параллельное изменение',data:'keep'});await route.continue();});await box.getByRole('button',{name:'Разобрать JSON и сравнить'}).click();await box.getByText(/Проект изменился после загрузки сцен/).waitFor();assert.equal(intercepted,true);assert.equal(await box.getByRole('button',{name:'Сравнить весь пакет'}).count(),0);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,2);await close(p);});

async function sceneBranchUI(f){const p=await page();await create(p);await send(p,'Обсудим процесс.');const box=p.getByLabel('Сцены в текущий диалог');await box.getByRole('button',{name:'Выбрать сцены для ветки'}).click();await box.getByLabel('Проект сцен для ветки').selectOption(f.project.id);await box.getByLabel('Раскадровка сцен для ветки').locator('option').filter({hasText:'Исходная'}).waitFor({state:'attached'});await box.getByLabel('Раскадровка сцен для ветки').selectOption(f.first.id);return {p,box};}
test('assistant scene branch: explicit copy preserves chat, models, draft and old project; next preview contains scenes',async()=>{const f=await revisionFixture(),{p,box}=await sceneBranchUI(f),oldId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),old=(await(await req('/assistant/conversations/'+oldId)).json()).data,n=calls().length;await p.getByLabel('Сообщение помощнику').fill('Черновик моего сообщения');await box.getByLabel('Последняя позиция для ветки').fill('2');await box.getByRole('button',{name:'Проверить сцены для ветки'}).click();await box.getByText('Полная копия сцен для ветки').waitFor();assert.equal(await box.getByRole('button',{name:'Создать ветку со сценами'}).isDisabled(),true);assert.equal((await(await req('/projects/'+f.project.id)).json()).data.artifacts.length,1);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByText('Полная копия сцен для ветки').scrollIntoViewIfNeeded();await shot(p,'assistant-scene-branch-light');await box.getByLabel('Подтверждаю сцены для ветки').check();await box.getByRole('button',{name:'Создать ветку со сценами'}).click();await p.getByText(/Создана ветка со сценами/).waitFor();const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),branch=(await(await req('/assistant/conversations/'+id)).json()).data;assert.notEqual(id,oldId);assert.equal(branch.parentId,oldId);assert.deepEqual(branch.messages,old.messages);assert.deepEqual(branch.roles,old.roles);assert.equal(JSON.parse(branch.context.documents.at(-1).text).rows[1].video,'СТАРЫЙ VIDEO 8');assert.deepEqual((await(await req('/assistant/conversations/'+oldId)).json()).data,old);assert.deepEqual((await(await req('/projects/'+f.project.id)).json()).data.artifacts,[f.first]);assert.equal(await p.getByLabel('Сообщение помощнику').inputValue(),'Черновик моего сообщения');assert.equal(calls().length,n);await p.getByLabel('Роль модели помощника').selectOption('imagePrompt');await p.getByRole('button',{name:'Проверить перед отправкой'}).click();await p.getByRole('button',{name:'Точный текст запроса'}).click();await p.getByText(/СТАРЫЙ VIDEO 8/).first().waitFor();assert.equal(calls().length,n);await close(p);});
test('assistant scene branch: selection change removes approval and stale project prevents branch',async()=>{const f=await revisionFixture(),{p,box}=await sceneBranchUI(f),old=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));await box.getByRole('button',{name:'Проверить сцены для ветки'}).click();await box.getByLabel('Подтверждаю сцены для ветки').check();await box.getByLabel('Последняя позиция для ветки').fill('2');assert.equal(await box.getByLabel('Подтверждаю сцены для ветки').count(),0);await box.getByRole('button',{name:'Проверить сцены для ветки'}).click();await box.getByLabel('Подтверждаю сцены для ветки').check();await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Другое',data:'keep'});await box.getByRole('button',{name:'Создать ветку со сценами'}).click();await box.getByText(/Проект или диалог изменились/).waitFor();assert.equal(await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),old);assert.equal(await box.getByLabel('Подтверждаю сцены для ветки').isChecked(),false);await close(p);});
