test('assistant scene branch HTTP: auth, origin, strict input, explicit consent and duplicate ID',async()=>{const f=await revisionFixture(),run=(await(await req('/assistant/conversations',{title:'Ветка',roles:{routine:null,script:null,imagePrompt:null,animationPrompt:null},documents:[]})).json()).data,ask={runId:run.id,attemptId:crypto.randomUUID(),projectId:f.project.id,artifactId:f.first.id,from:1,to:2};assert.equal((await req('/assistant/scene-branch-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/scene-branch-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);assert.equal((await req('/assistant/scene-branch-preview',{...ask,unknown:true})).status,400);const v=(await(await req('/assistant/scene-branch-preview',ask)).json()).data;assert.equal((await req('/assistant/scene-branches',{...ask,previewHash:v.hash,confirmed:false})).status,400);assert.equal((await req('/assistant/scene-branches',{...ask,previewHash:v.hash,confirmed:true})).status,200);assert.equal((await req('/assistant/scene-branches',{...ask,previewHash:v.hash,confirmed:true})).status,409);});
test('assistant scene branch: confirmed branch can finish after panel closes',async()=>{const f=await revisionFixture(),{p,box}=await sceneBranchUI(f);await box.getByRole('button',{name:'Проверить сцены для ветки'}).click();await box.getByLabel('Подтверждаю сцены для ветки').check();let release,seen;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);let id;await p.route('**/api/assistant/scene-branches',async route=>{id=JSON.parse(route.request().postData()).attemptId;seen();await gate;await route.continue();});await box.getByRole('button',{name:'Создать ветку со сценами'}).click();await started;await p.getByRole('button',{name:'Закрыть помощника'}).click();release();let branch;for(let i=0;i<100;i++){const r=await req('/assistant/conversations/'+id);if(r.ok){branch=(await r.json()).data;break;}await new Promise(resolve=>setTimeout(resolve,100));}assert.ok(branch,'Подтверждённая ветка должна сохраниться после закрытия панели');assert.equal(JSON.parse(branch.context.documents.at(-1).text).rows[0].image,'СТАРЫЙ IMAGE 7');await close(p);});
test('assistant scene branch: successful creation remains visible if history refresh fails',async()=>{const f=await revisionFixture(),{p,box}=await sceneBranchUI(f),old=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));await box.getByRole('button',{name:'Проверить сцены для ветки'}).click();await box.getByLabel('Подтверждаю сцены для ветки').check();await p.route('**/api/assistant/state',route=>route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:{message:'SYNTHETIC_HISTORY_ERROR'}})}));await box.getByRole('button',{name:'Создать ветку со сценами'}).click();await p.getByText(/Создана ветка со сценами/).waitFor();const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));assert.notEqual(id,old);assert.equal((await(await req('/assistant/conversations/'+id)).json()).data.parentId,old);await close(p);});
test('assistant document branch: mixed file review consent preserves old chat and next request',async()=>{const p=await page();await create(p);const n=calls().length,oldId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),old=(await(await req('/assistant/conversations/'+oldId)).json()).data;await p.getByLabel('Сообщение помощнику').fill('Черновик сохраняется');const box=p.getByLabel('Материалы в текущий диалог');await box.getByRole('button',{name:'Выбрать файлы для ветки'}).click();const f=docxUpload('Сначала уточнить стиль.');await box.getByLabel('Файлы для ветки',{exact:true}).setInputFiles([f,{name:'условия.txt',mimeType:'text/plain',buffer:Buffer.from('Город без выдумок.')}]);await box.getByRole('button',{name:'Проверить файлы для ветки'}).click();await box.getByText('Сначала уточнить стиль.').waitFor();assert.equal(await box.getByRole('button',{name:'Создать ветку с файлами'}).isDisabled(),true);assert.match(await box.innerText(),new RegExp(crypto.createHash('sha256').update(f.buffer).digest('hex')));await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByLabel('Подтверждаю файлы для ветки').scrollIntoViewIfNeeded();await shot(p,'assistant-document-branch-light');await box.getByLabel('Подтверждаю файлы для ветки').check();await box.getByRole('button',{name:'Создать ветку с файлами'}).click();await p.getByText(/Создана ветка с материалами/).waitFor();const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),branch=(await(await req('/assistant/conversations/'+id)).json()).data;assert.equal(branch.parentId,oldId);assert.deepEqual(branch.roles,old.roles);assert.deepEqual(branch.messages,old.messages);assert.deepEqual(branch.context.documents,[{name:f.name,text:'Сначала уточнить стиль.'},{name:'условия.txt',text:'Город без выдумок.'}]);assert.deepEqual((await(await req('/assistant/conversations/'+oldId)).json()).data,old);assert.equal(await p.getByLabel('Сообщение помощнику').inputValue(),'Черновик сохраняется');await p.getByRole('button',{name:'Проверить перед отправкой'}).click();await p.getByRole('button',{name:'Точный текст запроса'}).click();await p.getByText(/Город без выдумок/).first().waitFor();assert.equal(calls().length,n);await close(p);});
