test('assistant document branch HTTP: auth origin strict input consent replay and duplicate',async()=>{const run=(await(await req('/assistant/conversations',{title:'Ветка файлов',roles:{routine:null,script:null,imagePrompt:null,animationPrompt:null},documents:[]})).json()).data,ask={runId:run.id,attemptId:crypto.randomUUID(),documents:[{name:'rules.md',text:'Без выдумок'}]};assert.equal((await req('/assistant/document-branch-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/document-branch-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);assert.equal((await req('/assistant/document-branch-preview',{...ask,extra:true})).status,400);const v=(await(await req('/assistant/document-branch-preview',ask)).json()).data;assert.equal((await req('/assistant/document-branches',{...ask,previewHash:v.hash,confirmed:false})).status,400);const good=await req('/assistant/document-branches',{...ask,previewHash:v.hash,confirmed:true});assert.equal(good.status,200);const branch=(await good.json()).data;assert.equal((await req('/assistant/document-branches',{...ask,previewHash:v.hash,confirmed:true})).status,409);assert.equal((await req('/assistant/document-branch-preview',{...ask,runId:branch.id,attemptId:crypto.randomUUID()})).status,409);});
test('assistant document branch: confirmed save may finish after panel closes',async()=>{const p=await page();await create(p);const box=p.getByLabel('Материалы в текущий диалог');await box.getByRole('button',{name:'Выбрать файлы для ветки'}).click();await box.getByLabel('Файлы для ветки',{exact:true}).setInputFiles({name:'ветка.txt',mimeType:'text/plain',buffer:Buffer.from('Сохранить точный текст.')});await box.getByRole('button',{name:'Проверить файлы для ветки'}).click();await box.getByLabel('Подтверждаю файлы для ветки').check();let release,seen,id;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/document-branches',async route=>{id=JSON.parse(route.request().postData()).attemptId;seen();await gate;await route.continue();});await box.getByRole('button',{name:'Создать ветку с файлами'}).click();await started;await p.getByRole('button',{name:'Закрыть помощника'}).click();release();let branch;for(let i=0;i<100;i++){const r=await req('/assistant/conversations/'+id);if(r.ok){branch=(await r.json()).data;break;}await new Promise(resolve=>setTimeout(resolve,100));}assert.ok(branch,'Подтверждённая ветка должна сохраниться после закрытия панели');assert.deepEqual(branch.context.documents,[{name:'ветка.txt',text:'Сохранить точный текст.'}]);await close(p);});
test('assistant document revision: explicit same-name replacement compares both texts and preserves old branch',async()=>{const p=await page();await p.getByLabel('Файлы процесса помощника',{exact:true}).setInputFiles([{name:'условия.txt',mimeType:'text/plain',buffer:Buffer.from('Старое условие.')},{name:'стиль.md',mimeType:'text/markdown',buffer:Buffer.from('Сохранить стиль.')}]);await create(p);await send(p,'Обсудим процесс.');const n=calls().length,oldId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),old=(await(await req('/assistant/conversations/'+oldId)).json()).data;await p.getByLabel('Сообщение помощнику').fill('Черновик не терять');const box=p.getByLabel('Материалы в текущий диалог');await box.getByRole('button',{name:'Выбрать файлы для ветки'}).click();await box.getByLabel('Исключить материал 1').check();await box.getByLabel('Файлы для ветки',{exact:true}).setInputFiles({name:'условия.txt',mimeType:'text/plain',buffer:Buffer.from('Новое условие.')});await box.getByRole('button',{name:'Проверить файлы для ветки'}).click();await box.getByText('Старое условие.',{exact:true}).waitFor();await box.getByText('Новое условие.',{exact:true}).waitFor();assert.equal(await box.getByRole('button',{name:'Создать ветку с файлами'}).isDisabled(),true);assert.match(await box.innerText(),/переписка сохраняется.*исключённый текст/s);await box.getByLabel('Подтверждаю файлы для ветки').scrollIntoViewIfNeeded();await shot(p,'assistant-document-revision-dark');await box.getByLabel('Подтверждаю файлы для ветки').check();await box.getByRole('button',{name:'Создать ветку с файлами'}).click();await p.getByText(/Создана ветка с материалами/).waitFor();const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),b=(await(await req('/assistant/conversations/'+id)).json()).data;assert.equal(b.parentId,oldId);assert.deepEqual(b.context.documents,[{name:'стиль.md',text:'Сохранить стиль.'},{name:'условия.txt',text:'Новое условие.'}]);assert.deepEqual(b.messages,old.messages);assert.deepEqual((await(await req('/assistant/conversations/'+oldId)).json()).data,old);assert.equal(await p.getByLabel('Сообщение помощнику').inputValue(),'Черновик не терять');const preview=(await(await req('/assistant/preview',{id,question:'Проверь условия',task:'routine',currentPath:'/script',attemptId:crypto.randomUUID()})).json()).data;assert.deepEqual(JSON.parse(preview.user).context.documents,b.context.documents);assert.equal(calls().length,n);await close(p);});
