test('assistant document revision HTTP: strict indices, stale hash, consent, source remains',async()=>{const run=(await(await req('/assistant/conversations',{title:'Правка документов',roles:{routine:null,script:null,imagePrompt:null,animationPrompt:null},documents:[{name:'a.txt',text:'Старый'},{name:'b.txt',text:'Второй'}]})).json()).data,ask={runId:run.id,attemptId:crypto.randomUUID(),documents:[{name:'a.txt',text:'Новый'}],removeIndices:[0]};assert.equal((await req('/assistant/document-branch-preview',{...ask,removeIndices:[0,0]})).status,409);assert.equal((await req('/assistant/document-branch-preview',{...ask,removeIndices:[2]})).status,409);assert.equal((await req('/assistant/document-branch-preview',{...ask,removeIndices:[-1]})).status,400);const v=(await(await req('/assistant/document-branch-preview',ask)).json()).data;assert.equal(v.removedDocuments[0].text,'Старый');assert.equal((await req('/assistant/document-branches',{...ask,removeIndices:[1],previewHash:v.hash,confirmed:true})).status,409);assert.equal((await req('/assistant/document-branches',{...ask,previewHash:v.hash,confirmed:false})).status,400);const r=await req('/assistant/document-branches',{...ask,previewHash:v.hash,confirmed:true});assert.equal(r.status,200);assert.deepEqual((await(await req('/assistant/conversations/'+run.id)).json()).data,run);});
async function scriptBranchFixture(){const project=(await(await req('/projects',{title:'Версии сценария '+crypto.randomUUID().slice(0,6)})).json()).data,old=(await(await req('/projects/'+project.id+'/artifacts',{kind:'script',title:'Первая версия',data:{script:'  СТАРЫЙ СЦЕНАРИЙ\nВторая строка.  ',secret:'НЕ ПЕРЕНОСИТЬ'}})).json()).data,current=(await(await req('/projects/'+project.id+'/artifacts',{kind:'script',title:'Вторая версия',data:{script:'НОВЫЙ СЦЕНАРИЙ'}})).json()).data;return {project,old,current};}
async function scriptBranchUI(f){const p=await page();await create(p);const box=p.getByLabel('Сценарий в текущий диалог');await box.getByRole('button',{name:'Выбрать сценарий для ветки'}).click();await box.getByLabel('Проект сценария для ветки').selectOption(f.project.id);await box.getByLabel('Версия сценария для ветки').locator('option').filter({hasText:'Первая версия'}).waitFor({state:'attached'});return {p,box};}
test('assistant script branch: explicit old version full copy, consent and next model preview',async()=>{const f=await scriptBranchFixture(),{p,box}=await scriptBranchUI(f);await send(p,'Обсудим процесс.');await box.getByRole('button',{name:'Выбрать сценарий для ветки'}).click();await box.getByLabel('Проект сценария для ветки').selectOption(f.project.id);await box.getByLabel('Версия сценария для ветки').locator('option').filter({hasText:'Первая версия'}).waitFor({state:'attached'});const before=calls().length,oldId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),old=(await(await req('/assistant/conversations/'+oldId)).json()).data,project=(await(await req('/projects/'+f.project.id)).json()).data;await p.getByLabel('Сообщение помощнику').fill('Черновик сохранить');assert.equal(await box.getByRole('button',{name:'Проверить сценарий для ветки'}).isDisabled(),true);await box.getByLabel('Версия сценария для ветки').selectOption(f.old.id);await box.getByRole('button',{name:'Проверить сценарий для ветки'}).click();await box.getByText('Полный текст выбранного сценария').waitFor();assert.equal(await box.getByRole('button',{name:'Создать ветку со сценарием'}).isDisabled(),true);assert.match(await box.innerText(),/СТАРЫЙ СЦЕНАРИЙ/);await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByLabel('Подтверждаю сценарий для ветки').scrollIntoViewIfNeeded();await shot(p,'assistant-script-branch-light');await box.getByLabel('Подтверждаю сценарий для ветки').check();await box.getByRole('button',{name:'Создать ветку со сценарием'}).click();await p.getByText(/Создана ветка со сценарием/).waitFor();const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),branch=(await(await req('/assistant/conversations/'+id)).json()).data,copy=JSON.parse(branch.context.documents.at(-1).text);assert.equal(branch.parentId,oldId);assert.equal(copy.script,'  СТАРЫЙ СЦЕНАРИЙ\nВторая строка.  ');assert.equal(copy.artifactId,f.old.id);assert.equal(JSON.stringify(copy).includes('НЕ ПЕРЕНОСИТЬ'),false);assert.deepEqual(branch.messages,old.messages);assert.deepEqual(branch.roles,old.roles);assert.deepEqual((await(await req('/assistant/conversations/'+oldId)).json()).data,old);assert.deepEqual((await(await req('/projects/'+f.project.id)).json()).data,project);assert.equal(await p.getByLabel('Сообщение помощнику').inputValue(),'Черновик сохранить');const v=(await(await req('/assistant/preview',{id,question:'Проверь выбранный сценарий',task:'routine',currentPath:'/script',attemptId:crypto.randomUUID()})).json()).data;assert.equal(JSON.parse(JSON.parse(v.user).context.documents.at(-1).text).script,copy.script);assert.equal(calls().length,before);await close(p);});
test('assistant script branch: changed choice resets consent; stale project prevents saving',async()=>{const f=await scriptBranchFixture(),{p,box}=await scriptBranchUI(f),id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));await box.getByLabel('Версия сценария для ветки').selectOption(f.old.id);await box.getByRole('button',{name:'Проверить сценарий для ветки'}).click();await box.getByLabel('Подтверждаю сценарий для ветки').check();await box.getByLabel('Версия сценария для ветки').selectOption(f.current.id);assert.equal(await box.getByLabel('Подтверждаю сценарий для ветки').count(),0);await box.getByRole('button',{name:'Проверить сценарий для ветки'}).click();await box.getByLabel('Подтверждаю сценарий для ветки').check();await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Изменение',data:'x'});await box.getByRole('button',{name:'Создать ветку со сценарием'}).click();await box.getByText(/Проект или диалог изменились/).waitFor();assert.equal(await box.getByLabel('Подтверждаю сценарий для ветки').isChecked(),false);assert.equal(await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),id);await close(p);});
test('assistant script branch HTTP: auth origin strict consent stale duplicate and no rewrite',async()=>{const f=await scriptBranchFixture(),run=(await(await req('/assistant/conversations',{title:'Ветка сценария',roles:{routine:null,script:null,imagePrompt:null,animationPrompt:null},documents:[]})).json()).data,ask={runId:run.id,attemptId:crypto.randomUUID(),projectId:f.project.id,artifactId:f.old.id};assert.equal((await req('/assistant/script-branch-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/script-branch-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);assert.equal((await req('/assistant/script-branch-preview',{...ask,extra:true})).status,400);const v=(await(await req('/assistant/script-branch-preview',ask)).json()).data;assert.equal((await req('/assistant/script-branches',{...ask,previewHash:v.hash,confirmed:false})).status,400);const r=await req('/assistant/script-branches',{...ask,previewHash:v.hash,confirmed:true});assert.equal(r.status,200);const b=(await r.json()).data;assert.equal((await req('/assistant/script-branches',{...ask,previewHash:v.hash,confirmed:true})).status,409);assert.equal((await req('/assistant/script-branch-preview',{...ask,runId:b.id,attemptId:crypto.randomUUID()})).status,409);assert.deepEqual((await(await req('/assistant/conversations/'+run.id)).json()).data,run);});
test('assistant script branch: confirmed save can finish after panel closes',async()=>{const f=await scriptBranchFixture(),{p,box}=await scriptBranchUI(f);await box.getByLabel('Версия сценария для ветки').selectOption(f.old.id);await box.getByRole('button',{name:'Проверить сценарий для ветки'}).click();await box.getByLabel('Подтверждаю сценарий для ветки').check();let release,seen,id;const gate=new Promise(ok=>release=ok),started=new Promise(ok=>seen=ok);await p.route('**/api/assistant/script-branches',async route=>{id=JSON.parse(route.request().postData()).attemptId;seen();await gate;await route.continue();});await box.getByRole('button',{name:'Создать ветку со сценарием'}).click();await started;await p.getByRole('button',{name:'Закрыть помощника'}).click();release();let b;for(let i=0;i<100;i++){const r=await req('/assistant/conversations/'+id);if(r.ok){b=(await r.json()).data;break;}await new Promise(resolve=>setTimeout(resolve,100));}assert.ok(b);assert.equal(JSON.parse(b.context.documents.at(-1).text).artifactId,f.old.id);await close(p);});

test('assistant workflow export desktop: partial snapshot and exact private JSON download without AI',async()=>{
 const p=await page();await create(p);const area=await createWorkflowUI(p,'Экспорт контрольных точек');const exp=area.getByLabel('Выгрузка результатов процесса',{exact:true});
 assert.equal(await exp.getByRole('button',{name:'Посмотреть выгрузку процесса',exact:true}).isDisabled(),true);
 await sendWorkflow(p,'XIX век, все существенные условия заданы.');await area.getByRole('button',{name:'Принять результат шага',exact:true}).click();await area.getByText('Готов к запуску',{exact:true}).waitFor();
 const n=calls().length;await exp.getByRole('button',{name:'Посмотреть выгрузку процесса',exact:true}).click();await exp.getByText('Полный текст JSON',{exact:true}).waitFor();const text=await exp.locator('pre').textContent(),obj=JSON.parse(text);assert.equal(obj.workflow.accepted,1);assert.equal(obj.workflow.total,2);assert.equal(obj.accepted.length,1);assert.equal(obj.accepted[0].step.task,'routine');
 const button=exp.getByRole('button',{name:'Скачать JSON результатов',exact:true});assert.equal(await button.isDisabled(),true);await exp.getByLabel('Проверил содержимое и согласен скачать приватную копию',{exact:true}).check();const [download]=await Promise.all([p.waitForEvent('download'),button.click()]);const saved=await download.path();assert.equal(fs.readFileSync(saved,'utf8'),text);assert.match(download.suggestedFilename(),/^tubestudio-process-.*\.json$/);assert.equal(calls().length,n);
 await exp.scrollIntoViewIfNeeded();await shot(p,'assistant-workflow-export-dark');await sendWorkflow(p);await area.getByRole('button',{name:'Принять результат шага',exact:true}).click();await area.getByText('Все шаги приняты',{exact:true}).waitFor();assert.equal(await exp.getByRole('button',{name:'Скачать JSON результатов',exact:true}).count(),0);await exp.getByRole('button',{name:'Посмотреть выгрузку процесса',exact:true}).click();await exp.getByText('Полный текст JSON',{exact:true}).waitFor();assert.equal(JSON.parse(await exp.locator('pre').textContent()).accepted.length,2);assert.equal(calls().length,n+1);await close(p);
});

