test('saved prompt note HTTP: authentication, origin, strict schema and snapshot',async()=>{const f=await savedPromptFixture(),x=(await(await req('/assistant/storyboard-excerpt-preview',{projectId:f.project.id,artifactId:f.first.id,from:2,to:2})).json()).data,ask={projectId:f.project.id,sourceSnapshot:x.projectSnapshot,noteId:f.note.id,field:'image'};assert.equal((await req('/assistant/prompt-note-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/prompt-note-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);assert.equal((await req('/assistant/prompt-note-preview',{...ask,extra:true})).status,400);assert.equal((await req('/assistant/prompt-note-preview',ask)).status,200);await req('/projects/'+f.project.id+'/artifacts',{kind:'note',title:'Изменение',data:'x'});assert.equal((await req('/assistant/prompt-note-preview',ask)).status,409);});

