test('assistant channel picker: local preview, explicit YouTube listing, separate source and AI consent',async()=>{const p=await page();await create(p);const box=p.getByLabel('Выбор ролика канала'),start=calls().length,models=calls().filter(c=>c.model).length;await box.getByRole('button',{name:'Выбрать ролик канала'}).click();await box.getByLabel('Канал-донор').fill('@fixture');await box.getByRole('button',{name:'Проверить запрос списка канала'}).click();await box.getByText(/Базово до 3 единиц/).waitFor();assert.equal(calls().length,start);await box.getByRole('button',{name:'Подтвердить получение списка канала'}).click();await box.getByText('Синтетический канал',{exact:false}).waitFor();assert.deepEqual(calls().slice(start).map(c=>c.endpoint.split('/').at(-1)),['channels','playlistItems','videos']);assert.match(await box.innerText(),/есть следующая страница/);assert.equal(await p.getByLabel('Источник YouTube').inputValue(),'');await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByText('История города · донор',{exact:false}).scrollIntoViewIfNeeded();await shot(p,'assistant-channel-light');await box.getByRole('button',{name:'Выбрать этот ролик'}).first().click();assert.equal(await p.getByLabel('Источник YouTube').inputValue(),'https://www.youtube.com/watch?v=abcdefghijk');assert.equal(calls().length,start+3);await p.getByRole('button',{name:'Проверить получение источника'}).click();assert.equal(calls().length,start+3);await p.getByRole('button',{name:'Подтвердить получение с YouTube'}).click();await p.getByRole('link',{name:'История города · донор'}).waitFor();assert.deepEqual(calls().slice(start+3).map(c=>c.endpoint.split('/').at(-1)),['videos','commentThreads']);assert.equal(calls().filter(c=>c.model).length,models);await close(p);});
