test('assistant channel HTTP: auth, origin, schema, explicit consent and replay',async()=>{const run=(await(await req('/assistant/conversations',{title:'Канал',roles:{routine:null,script:null,imagePrompt:null,animationPrompt:null},documents:[]})).json()).data,ask={runId:run.id,attemptId:crypto.randomUUID(),channel:'@fixture'},before=calls().length;assert.equal((await req('/assistant/channel-preview',ask,null)).status,401);assert.equal((await fetch(BASE+'/api/assistant/channel-preview',{method:'POST',headers:{Cookie:cookie,Origin:'https://foreign.invalid','content-type':'application/json'},body:JSON.stringify(ask)})).status,403);assert.equal((await req('/assistant/channel-preview',{...ask,extra:true})).status,400);const v=(await(await req('/assistant/channel-preview',ask)).json()).data;assert.equal((await req('/assistant/channel-uploads',{...ask,previewHash:v.hash,confirmed:false})).status,400);assert.equal(calls().length,before);const r=await req('/assistant/channel-uploads',{...ask,previewHash:v.hash,confirmed:true});assert.equal(r.status,200);const job=(await r.json()).data;await(await req('/jobs/'+job.jobId+'/stream')).text();assert.equal((await req('/assistant/channel-uploads',{...ask,previewHash:v.hash,confirmed:true})).status,409);assert.deepEqual((await(await req('/assistant/conversations/'+run.id)).json()).data,run);});

test('assistant source branch: five videos, local consent, immutable branch and no extra requests',async()=>{
 const p=await page();await create(p);const models=calls().filter(c=>c.model).length;
 for(const [i,id] of ['abcdefghijk','lmnopqrstuv','0123456789a','0123456789b','0123456789c'].entries()){
  const previousId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));await p.getByLabel('Источник YouTube',{exact:true}).fill('https://youtu.be/'+id);await p.getByRole('button',{name:'Проверить получение источника',exact:true}).click();await p.getByRole('button',{name:'Подтвердить получение с YouTube',exact:true}).click();
  await p.waitForFunction(id=>localStorage.getItem('ts:assistant:last')!==id,previousId);if(i<4)await p.waitForFunction(()=>{const e=document.querySelector('input[aria-label="Источник YouTube"]');return e&&!e.disabled&&e.value==='';});
 }
 assert.equal(await p.getByLabel('Источник YouTube',{exact:true}).count(),0);const before=calls().length,oldId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),old=(await(await req('/assistant/conversations/'+oldId)).json()).data;assert.equal(old.context.sources.length,5);
 await p.getByLabel('Сообщение помощнику',{exact:true}).fill('Мой несохранённый вопрос');const box=p.getByLabel('Источники в ветке');await box.getByRole('button',{name:'Выбрать источники для исключения'}).click();await box.getByLabel('Исключить источник 2').check();await box.getByRole('button',{name:'Проверить источники для ветки'}).click();await box.getByText('Останутся: 4').waitFor();assert.equal(calls().length,before);assert.equal(await box.getByRole('button',{name:'Создать ветку без источников'}).isDisabled(),true);
 await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await box.getByText('Останутся: 4').scrollIntoViewIfNeeded();await shot(p,'assistant-source-branch-light');await box.getByLabel('Подтверждаю исключение источников').check();await box.getByRole('button',{name:'Создать ветку без источников'}).click();await p.getByText(/Создана ветка с изменённым набором источников/).waitFor();assert.equal(calls().length,before);assert.equal(calls().filter(c=>c.model).length,models);assert.equal(await p.getByLabel('Сообщение помощнику',{exact:true}).inputValue(),'Мой несохранённый вопрос');const newId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),branch=(await(await req('/assistant/conversations/'+newId)).json()).data;assert.equal(branch.parentId,old.id);assert.equal(branch.context.sources.length,4);assert.equal(branch.context.sources.some(s=>s.id===old.context.sources[1].id),false);assert.deepEqual((await(await req('/assistant/conversations/'+oldId)).json()).data,old);assert.equal(p.errors.length,0);await close(p);
});

