 await box.getByRole('button',{name:'Проверить запрос списка канала'}).click();await box.getByRole('button',{name:'Подтвердить получение списка канала'}).click();await box.getByText('Синтетический канал',{exact:false}).waitFor();const previousId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last'));await p.getByRole('button',{name:'Новый диалог / модели'}).click();await p.getByLabel('Название задачи помощника').fill('Независимый диалог');await p.getByRole('button',{name:'Создать локальный диалог'}).click();await p.waitForFunction(id=>localStorage.getItem('ts:assistant:last')!==id,previousId);await p.getByLabel('Сообщение помощнику').waitFor();box=p.getByLabel('Выбор ролика канала');assert.equal(await box.getByText('Синтетический канал',{exact:false}).count(),0);assert.equal(await box.getByRole('button',{name:'Выбрать ролик канала'}).count(),1);
 await box.getByRole('button',{name:'Выбрать ролик канала'}).click();await box.getByLabel('Канал-донор').fill('@fixture');await box.getByRole('button',{name:'Проверить запрос списка канала'}).click();await box.getByRole('button',{name:'Подтвердить получение списка канала'}).click();await box.getByText('Синтетический канал',{exact:false}).waitFor();const last=calls().length;await p.getByRole('button',{name:'Закрыть помощника'}).click();await p.getByRole('button',{name:'Открыть помощника'}).click();await p.getByLabel('Сообщение помощнику').waitFor();assert.equal(await p.getByLabel('Выбор ролика канала').getByText('Синтетический канал',{exact:false}).count(),0);assert.equal(calls().length,last);await close(p);
