test('assistant channel pages HTTP: strict input and approval bind token and channel',async()=>{
 const run=(await(await req('/assistant/conversations',{title:'Страницы',roles:{routine:null,script:null,imagePrompt:null,animationPrompt:null},documents:[]})).json()).data,ask={runId:run.id,attemptId:crypto.randomUUID(),channel:'@fixture',page:{token:'NEXT_NOT_FETCHED',expectedChannelId:'UC'+'a'.repeat(22)}},before=calls().length;
 assert.equal((await req('/assistant/channel-preview',ask,null)).status,401);assert.equal((await req('/assistant/channel-preview',{...ask,page:{...ask.page,other:true}})).status,400);assert.equal((await req('/assistant/channel-preview',{...ask,page:{...ask.page,token:'\n'}})).status,400);const v=(await(await req('/assistant/channel-preview',ask)).json()).data;assert.equal(calls().length,before);assert.equal((await req('/assistant/channel-uploads',{...ask,previewHash:v.hash,confirmed:false})).status,400);assert.equal((await req('/assistant/channel-uploads',{...ask,page:{...ask.page,token:'PAGE_THREE'},previewHash:v.hash,confirmed:true})).status,409);const r=await req('/assistant/channel-uploads',{...ask,previewHash:v.hash,confirmed:true});assert.equal(r.status,200);const job=(await r.json()).data;await(await req('/jobs/'+job.jobId+'/stream')).text();assert.deepEqual(calls().slice(before).map(c=>c.endpoint.split('/').at(-1)),['channels','playlistItems','videos']);assert.equal((await req('/assistant/channel-uploads',{...ask,previewHash:v.hash,confirmed:true})).status,409);assert.deepEqual((await(await req('/assistant/conversations/'+run.id)).json()).data,run);
});

