test('assistant channel snapshot: explicit selected metadata becomes immutable branch document without network',async()=>{
 const p=await page();await create(p);const box=await reusableChannel(p);await box.getByRole('button',{name:'Проверить следующую страницу'}).click();await box.getByRole('button',{name:'Подтвердить получение следующей страницы'}).click();await box.getByText(/Страница 2 · позиций: 2/).waitFor();const before=calls().length,oldId=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),old=(await(await req('/assistant/conversations/'+oldId)).json()).data;await p.getByLabel('Сообщение помощнику').fill('Сравним эти ролики');
 await box.getByLabel('В копию: страница 1, позиция 1').check();await box.getByLabel('В копию: страница 2, позиция 2').check();await box.getByLabel('Поиск в полученных роликах').fill('город');const snap=box.getByLabel('Копия выбранных роликов для ветки');assert.match(await snap.innerText(),/Отмечено позиций: 2\/20/);await snap.getByRole('button',{name:'Проверить копию роликов'}).click();await snap.getByText('Полная копия выбранных метаданных').waitFor();const text=await snap.locator('pre').textContent(),copy=JSON.parse(text);assert.deepEqual(copy.positions.map(x=>x.id),['abcdefghijk','lmnopqrstuv']);assert.equal(copy.positions[1].duplicate,true);assert.equal(text.includes('NEXT_NOT_FETCHED'),false);assert.equal(calls().length,before);assert.equal(await snap.getByRole('button',{name:'Создать ветку с копией роликов'}).isDisabled(),true);
 await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await snap.getByText('Полная копия выбранных метаданных').scrollIntoViewIfNeeded();await shot(p,'assistant-channel-snapshot-light');await snap.getByLabel('Подтверждаю копию роликов').check();await snap.getByRole('button',{name:'Создать ветку с копией роликов'}).click();await p.waitForFunction(id=>localStorage.getItem('ts:assistant:last')!==id,oldId);await p.getByText(/Создана ветка с копией метаданных роликов/).waitFor();const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),branch=(await(await req('/assistant/conversations/'+id)).json()).data;assert.equal(branch.parentId,oldId);assert.deepEqual(branch.messages,old.messages);assert.deepEqual(branch.roles,old.roles);assert.equal(branch.context.documents.at(-1).text,text);assert.deepEqual((await(await req('/assistant/conversations/'+oldId)).json()).data,old);assert.equal(await p.getByLabel('Сообщение помощнику').inputValue(),'Сравним эти ролики');assert.equal(calls().length,before);await p.getByRole('button',{name:'Проверить перед отправкой'}).click();await p.getByRole('button',{name:'Точный текст запроса'}).click();assert.match(await p.getByRole('dialog').innerText(),/tubestudio-channel-selection/);assert.equal(calls().length,before);await close(p);
});
