 await p.setViewportSize({width:1024,height:900});await p.evaluate(()=>{document.documentElement.classList.remove('dark');document.documentElement.classList.add('light');});await nav.getByRole('button',{name:'Сообщение',exact:true}).click();await shot(p,'assistant-navigation-light-1024');await close(p);
