 await part.getByLabel('Большой текстовый файл').setInputFiles({name:'wide.md',mimeType:'text/plain',buffer:Buffer.from('x'.repeat(1200)+'\nпоследняя строка')});await part.getByText(/строк\. Строки разделены/).waitFor();await part.getByLabel('Начальная строка фрагмента').fill('2');await part.getByLabel('Конечная строка фрагмента').fill('2');await part.getByRole('button',{name:'Проверить фрагмент',exact:true}).click();await part.getByLabel('Подтверждаю фрагмент текста').check();await part.getByRole('button',{name:'Добавить проверенный фрагмент'}).click();await box.getByRole('button',{name:'Проверить файлы для ветки'}).click();await box.getByText(/В новой ветке: 4\/4 материалов/).waitFor();await box.getByLabel('Подтверждаю файлы для ветки').check();await box.getByRole('button',{name:'Создать ветку с файлами'}).click();await p.getByText(/Создана ветка с материалами/).waitFor();const id=await p.evaluate(()=>localStorage.getItem('ts:assistant:last')),docs=(await(await req('/assistant/conversations/'+id)).json()).data.context.documents;assert.equal(docs.length,4);assert.match(docs[2].text,/"fromLine":1,"toLine":1/);assert.match(docs[3].text,/последняя строка/);await close(p);
